INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(496, 'koKR', 'Eliksir męki', 'Ach, kolejny parszywy dzień w Smolnym Młynie. Całe to czyste powietrze wprawia mnie w taki podły nastrój, $N.$b$bIm prędzej zarazimy tutejszych ludzi, tym lepiej. Prowadzę intensywne badania nad substancjami zabójczymi, których mógłbym użyć w swoich miksturach, ale nie mam czasu, by je wszystkie zebrać.$b$bJeśli chcesz się na coś przydać, zdobądź dla mnie następujące rzeczy: 10 języków szarego niedźwiedzia i bardzo rzadką, trudną do znalezienia posokę pełzacza. Zarówno niedźwiedzie, jak i pełzacze znajdziesz tuż za Smolnym Młynem.', 'Aptekarz Lydon ze Smolnego Młyna chce 10 języków szarego niedźwiedzia i trochę posoki pełzacza.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(501, 'koKR', 'Eliksir bólu', 'Och, $N... w Międzygórzu kwitną kwiaty, a powietrze jest takie świeże i rześkie. Nie mogę się powstrzymać, by nie pławić się w tej całej udręce. Wyglądam przez moje brudne okno i tęsknię za dniem, w którym nasza Nowa Zaraza przyniesie temu światu śmierć, na jaką zasługuje.$b$bChoć z przyjemnością siedziałbym i dumał ponuro przez cały dzień, wzywa mnie obowiązek wobec Mrocznej Pani. Pomożesz mi? Moje badania każą mi sądzić, że z krwi lwa górskiego zdołam przyrządzić najwspanialszy śmiercionośny wywar. Przynieś mi jej trochę, a zabawimy się.', 'Przynieś 10 fiolek krwi lwa górskiego aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(509, 'koKR', 'Eliksir agonii', 'Kolejny dzień, kolejny eliksir do przyrządzenia. Gdyby to zależało ode mnie, pozwoliłbym żałosnym ludziom i Pladze po prostu wybić się nawzajem. I tak wydają się do tego zdeterminowani.$b$bNiestety, nasza Mroczna Pani chce nieco przyspieszyć ten proces, więc czemu nie umilić sobie tych ponurych dni, szerząc po kraju odrobinę śmierci i chorób?$b$bOto plan, $N: udasz się do Zagrody Nethandera, na południe od Smolnego Młyna i na wschód od rzeki i Południowego Brzegu. Zbierz dla mnie z pola 6 kwiatów błotopyska do mojego następnego eliksiru.', 'Przynieś 6 kwiatów błotopyska aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(515, 'koKR', 'Eliksir agonii', 'Kompozyt z błotopyska? Genialne! Czemu sam na to nie wpadłem?$b$bPozwól, że dodam mój koloid rozkładu do tego diabelskiego wywaru.$b$bBy uaktywnić czynniki zakaźne w tej mieszance z błotopyska, Lydon będzie potrzebował silnego eliksiru krwi trolla, a także łusek Sztyletogrzbietych i oczu Poszarpanopłetwych z południowego wybrzeża Międzygórza. Kiedy zbierzesz dla niego wszystkie składniki, będzie wiedział, co robić. Ach, jakże nie mogę się doczekać wieści o jego eksperymencie!', 'Przynieś Miksturę z błotopyska, Silny eliksir krwi trolla, 5 łusek Sztyletogrzbietych i 5 oczu Poszarpanopłetwych aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(517, 'koKR', 'Eliksir agonii', 'Nowy eliksir jest wreszcie gotowy do próby. Ale po co marnować doskonałą, wysoce zakaźną zarazę na zwykłą żabę czy psa? Zabawmy się naprawdę w imię lady Sylwany.$b$bUdaj się do Dun Garok. Wiesz, do tych koszar, po których kręcą się te plugawe małe krasnoludy. Ukradnij mi beczkę ich stouta Shindiggera. Kiedy już ją dostanę, urządzimy sobie niezłą imprezę, $N.', 'Przynieś beczkę stouta Shindiggera aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(784, 'koKR', 'Pokonaj zdrajców', 'Pod wodzą admirała Proudmoore\'a ludzie z Kul Tiras wtargnęli do Durotaru, łamiąc pakt, który wódz zawarł z Jainą Proudmoore, by przed laty pokonać Archimonda.$b$bLudzka agresja została odparta, a Twierdza Tiragarde padła. Jednak niedawno rezerwy admirała pod wodzą porucznika Benedicta odbiły twierdzę i znów zagrażają naszej ojczyźnie. Ci ludzie nie mają za grosz szacunku dla dyplomacji.$b$bDowiedź swojego honoru – ruszaj na południe do Twierdzy Tiragarde i zgładź ludzkich najeźdźców.', 'Zabij 10 marynarzy z Kul Tiras, 8 żołnierzy piechoty morskiej z Kul Tiras oraz porucznika Benedicta, po czym wróć do Gar\'Thoka w Brzytwogórze.', '', 'Wróć do Gar\'Thoka w Durotarze.', '', '', '', '', 0),
(785, 'koKR', 'Strategiczny sojusz', 'Thrall to niezwykle mądry i szlachetny przywódca. Jego nieustępliwości na polu bitwy dorównuje jedynie jego dyplomatyczny takt.$b$bTrolle Mrocznej Włóczni okazały się bezcennymi sojusznikami orczego ludu. Z lojalności i honoru zawarliśmy z nimi pakt obronny.$b$bWódz rozkazał upewnić się, że naszym przyjaciołom z Mrocznej Włóczni w Wiosce Sen\'jin nie grozi bezpośrednie niebezpieczeństwo. Jeden z ich najbardziej zaufanych zwiadowców, Lar Skradokieł, uważnie pilnuje ich zachodniej flanki.$b$bOdszukaj Lara i pomóż mu, jeśli będzie trzeba.', 'Odszukaj Lara Skradokła na zachodniej flance Wioski Sen\'jin.', '', '', '', '', '', '', 0),
(786, 'koKR', 'Powstrzymać agresję Kolkarów', 'Ścisz głos, $N. Centaury Kolkarów są tuż za grzbietem na zachodzie, na Turni Kolkarów.$b$bZeszłej nocy, gdy wyruszyli na łupieżczy wypad, zakradłem się do ich wioski i odkryłem, że te plugawe bestie zaplanowały potrójny atak na trolle i orków Durotaru.$b$bNie możemy dopuścić, by ich najazd się powiódł. Może zdołasz zebrać dość siły, by zakraść się na Turnię Kolkarów i zniszczyć ich plany ataku.$b$bO ile dobrze widziałem, podzielili je między trzech swoich przywódców.', 'Lar Skradokieł spod Wioski Sen\'jin chce, żebyś $gzniszczył:zniszczyła; 3 plany ataku przechowywane na Turni Kolkarów.', '', 'Wróć do Lara Skradokła w Wiosce Sen\'jin w Durotarze.', 'Plan ataku: Dolina Prób – zniszczony', 'Plan ataku: Wioska Sen\'jin – zniszczony', 'Plan ataku: Orgrimmar – zniszczony', '', 0),
(787, 'koKR', 'Nowa Horda', 'Throm\'ka, $N. Jestem Eitrigg. Thrall powierzył mi nadzór nad szkoleniem rekrutów.$b$bHorda nie jest już tym, czym była kiedyś. Był czas, gdy odszedłem z Hordy, rozczarowany rosnącymi wpływami żądnych władzy pionków Płonącego Legionu. Na wygnaniu wpadłem w ręce grupy ludzi, ale uratował mnie wódz. Gdy usłyszałem jego wizję Hordy wolnej od demonicznych wpływów, prowadzonej przez szamanów, wróciłem.$b$bGornek przekaże ci dalsze instrukcje.', 'Zgłoś się do Gorneka w Norze.', '', '', '', '', '', '', 0),
(788, 'koKR', 'Ząbkowanie', 'Na początek trzeba ci trochę wzmocnić kręgosłup. Mógłbym cię wysłać na Pustkowia na polowanie na kodo, ale szczerze mówiąc, $gżywy:żywa; przydasz się nam bardziej niż $gmartwy:martwa;.$b$bMyślę, że godnym przeciwnikiem będą dla ciebie cętkowane dziki, które znajdziesz na północ stąd.', 'Zabij 8 cętkowanych dzików, a potem wróć do Gorneka w Norze.', '', 'Wróć do Gorneka w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(789, 'koKR', 'Żądło skorpiady', 'Od jadowitego żądła skorpiady padali zarówno potężni wojownicy, jak i niezdarni nowicjusze. Mnóstwo skorpiad znajdziesz na północny zachód stąd. Przynieś mi osiem ich ogonów jako dowód twojej sprawności w boju.$b$bAntidotum na ich żądło wytwarza się właśnie z jadu pobranego z ich kolców. Trzymamy pod ręką spore zapasy antidotum na jad skorpiad, żeby leczyć takich młodzików jak ty...$b$bAle ty z pewnością nie będziesz go $gpotrzebował:potrzebowała;, prawda?', 'Zdobądź 8 ogonów skorpiady robotnicy dla Gorneka w Norze.', '', 'Wróć do Gorneka w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(790, 'koKR', 'Sarkoth', '$N! Myślałem, że umrę tu, a nikt się o tym nie dowie. Gdy polowałem na skorpiady w Dolinie, natknąłem się na wyjątkowo groźnie wyglądającą sztukę. Rzuciłem się na nią i zdołałem potężnie uderzyć ją w pazur, zanim zacisnął się na mojej nodze.$b$bNie byłem jednak gotów na jej żądło – spadło w dół, prosto w moją pierś, rozcięło ciało i puściło mi krew. Proszę, musisz zabić tę skorpiadę za mnie! Mój honor musi zostać obroniony! Walczyłem z nią na płaskowyżu na południu.', 'Zabij Sarkotha i przynieś jego pazur Hana\'zui.', '', 'Wróć do Hana\'zuy w Durotarze.', '', '', '', '', 0),
(791, 'koKR', 'Każdy nosi swój ciężar', 'Wiek uczynił mnie bezużytecznym w walce. Teraz przydaję się na inne sposoby.$b$bZ tego punktu obserwacyjnego wypatruję najeźdźców. Odkąd rośnie tu nasza siła, coraz rzadziej dmę w róg sygnałowy.$b$bŻeby zabić czas, wyrabiam rzeczy, które pomagają młodszym, sprawniejszym wojownikom bronić naszej ojczyzny.$b$bTobie mogę zrobić torbę na dobytek. Jeśli taka rzecz by ci się przydała, przynieś mi trochę płótna – materiału, którego ludzie i centaury mają pod dostatkiem.', 'Furl Pogardobrwy na wieży strażniczej w Brzytwogórze chce 8 skrawków płótna.', '', 'Wróć do Furla Pogardobrwego w Brzytwogórze w Durotarze.', '', '', '', '', 0),
(792, 'koKR', 'Plugawe chowańce', 'Ufam, że Dolina Prób wiele cię nauczy, $N.$B$BZostałam wysłana do Doliny, by cię prowadzić, ale odkryłam tu rosnące skażenie...$B$BGrupa, która nazywa siebie Płonącym Ostrzem, ma tu, w Dolinie Prób, swój sabat. Czają się w jaskini na północnym wschodzie, a ich plugawe chowańce wylały się z jej wylotu i sieją spustoszenie.$B$BW ramach pierwszego zadania przeciw Płonącemu Ostrzu nakazuję ci pokonać te chowańce. Zabij ich wiele, a jeśli przeżyjesz, wróć do mnie.', 'Zabij 8 plugawych chowańców.$B$BWróć do Zureethy Dalekowzrocznej przed Norą.', '', 'Wróć do Zureethy Dalekowzrocznej w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(794, 'koKR', 'Medalion Płonącego Ostrza', 'Moje wróżby ukazują mi, że w głębi Sabatu Płonącego Ostrza ukryty jest przedmiot mocy, strzeżony przez bestie i czarną magię.$B$BTo Medalion Płonącego Ostrza, a twoim kolejnym zadaniem jest go odnaleźć i wynieść z sabatu.$B$BUważaj jednak, bo medalion może być w rękach sługi Płonącego Ostrza, a wtedy jego moc przewyższy moc chowańców, które już $gnapotkałeś:napotkałaś;.$B$BIdź, $N. Sabat znajdziesz w jaskini na północnym zachodzie.', 'Przynieś Medalion Płonącego Ostrza Zureecie Dalekowzrocznej przed Norą.', '', 'Wróć do Zureethy Dalekowzrocznej w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(804, 'koKR', 'Sarkoth', 'To, czego dla mnie $gdokonałeś:dokonałaś;, hartuje moje serce. Nie mogę tak łatwo upaść! Muszę wytrwać!$b$bNie zmienia to jednak faktu, że nie zdołam sam wrócić do Nory. Proszę, $n, wróć do Nory i powiedz Gornekowi o moim położeniu. Może on zdoła mi pomóc.', 'Przekaż Gornekowi w Norze wieść o ciężkim położeniu Hana\'zuy.', '', '', '', '', '', '', 0),
(805, 'koKR', 'Zamelduj się w Wiosce Sen\'jin', 'Twoje próby w walce z Płonącym Ostrzem dobiegły końca... tu, w Dolinie. Chcę jednak, żebyś $gzłożył:złożyła; raport ze swoich odkryć.$B$BUdaj się do Sen\'jin, wioski trolli, i odszukaj mistrza Gadrina. Wioska Sen\'jin leży na wschód od doliny, a potem w prawo na rozwidleniu.$B$BPowiedz Gadrinowi o Płonącym Ostrzu i o tym, że dotarli do Doliny Prób. Dowiedz się od niego, czy dotarli już do Sen\'jin.$B$BIdź, $N, i się pospiesz. Obawiam się, że zło znalezione w Sabacie Płonącego Ostrza to tylko zwiastun większego zagrożenia...', 'Porozmawiaj z mistrzem Gadrinem w Wiosce Sen\'jin.', '', '', '', '', '', '', 0),
(806, 'koKR', 'Mroczne burze', 'Nie możemy pozwolić, by Płonące Ostrze zdobyło przyczółek w Durotarze! Musimy ich zniszczyć, zanim ich zło się rozjątrzy!$B$BPrzeprowadziłem własne śledztwo i odkryłem, że czarnoksiężnik Płonącego Ostrza, goblin Fizzle Mroczna Burza, rozbił obóz na Grani Grzmotu na północnym zachodzie. Stamtąd wraz ze swoimi sługami z kultu sieje chaos.$B$BZnajdź i pokonaj Fizzle\'a, a potem przynieś mi jego martwy pazur!', 'Przynieś pazur Fizzle\'a Orgnilowi Bliźnie Duszy w Brzytwogórze.', '', 'Wróć do Orgnila Blizny Duszy w Durotarze.', '', '', '', '', 0),
(807, 'koKR', '', 'Moi zwiadowcy donoszą, że część zwierząt w Durotarze została zarażona demonicznym skażeniem. Widziano je na północy i na zachodzie.$B$BKrążą wśród pobratymców jak zwykłe bestie, ale płyną przez nie złe moce, a w każdej z nich płonie serce osmalone czarną magią.$B$BTe bestie trzeba zniszczyć!$B$BJeśli podczas wędrówek po Durotarze natkniesz się na takie zwierzę, zabij je i zabierz jego osmalone serce. Przynieś mi te serca, a każę je zbadać, a potem zniszczyć.', 'Przynieś 5 osmalonych serc Orgnilowi Bliźnie Duszy w Brzytwogórze.', '', 'Wróć do Orgnila Blizny Duszy w Durotarze.', '', '', '', '', 0),
(808, 'koKR', 'Czaszka Minshiny', 'Słyszę w snach głos mojego brata, Minshiny, który mnie woła.$B$BPorwał go Zalazane, czarnoksiężnik z Wysp Echa na wschodzie. I mój brat nie żyje.$B$BAle śmierć nie oznacza dla niego wolności. Magia Zalazanego uwięziła ducha Minshiny w jego własnej czaszce. W snach widzę ją wśród innych czaszek, w kręgu mocy na największej z Wysp Echa. Dopóki tam pozostaje, dusza mojego brata jest potępiona.$B$BProszę, $N. Znajdź krąg i odzyskaj czaszkę Minshiny. Przynieś mi ją.$B$BUwolnij go!', 'Odzyskaj czaszkę Minshiny z kręgu mocy na Wyspach Echa.$B$BPrzynieś ją mistrzowi Gadrinowi w Wiosce Sen\'jin.', '', 'Wróć do mistrza Gadrina w Wiosce Sen\'jin w Durotarze.', '', '', '', '', 0),
(809, 'koKR', 'Ak\'Zeloth', 'Od ostatniej wielkiej wojny, w której pokonano Płonący Legion, szukam wśród orków źródeł demonicznego zepsucia. Kołnierz, który mi $gprzyniosłeś:przyniosłaś;, potwierdza moje obawy.$B$BNależy do Płonącego Ostrza, kultu skupionego wokół przedmiotu o demonicznej mocy. Nazywa się go Demonicznym Nasionem i spoczywa na Pustkowiach, na Szczycie Upiornej Mgły. Trzeba go zniszczyć!$B$BUdaj się do Wysuniętego posterunku na granicy Pustkowi, na zachodzie, i porozmawiaj z moim pomocnikiem, Ak\'Zelothem. On wskaże ci dalszą drogę.', 'Porozmawiaj z Ak\'Zelothem na Pustkowiach.', '', '', '', '', '', '', 0),
(810, 'koKR', '', 'Dobrze ci zrobi, jeśli się nauczysz, jak niebezpieczna potrafi być ta kraina.$B$BTutejsze zwierzęta mogą nas tego nauczyć... jeśli jesteśmy mądrzy i spostrzegawczy.$B$BSkorpiady to doskonały przykład przetrwania w Durotarze. Jeśli chcesz przetrwać, rozsądnie będzie przyswoić sobie niektóre ich cechy. Ich twarde pancerze mogą cię ochronić przed żarem słońca, a nawet przed zabójczą bronią.$B$BPrzynieś mi 6 małych pancerzy skorpiad od klekoczących skorpiad, $N, a postaram się sprawiedliwie cię nagrodzić.', 'Przynieś 6 małych pancerzy skorpiad Kor\'ghanowi w Wiosce Sen\'jin.', '', '', '', '', '', '', 0),
(811, 'koKR', '', 'Inną cechą skorpiad jest ich zaciekła lojalność. Chronią się nawzajem, gdy grozi im niebezpieczeństwo – pewnie już to $gwidziałeś:widziałaś; podczas swojego pierwszego polowania na skorpiady.$B$BDobrze zrobisz, jeśli weźmiesz sobie tę lekcję do serca: razem jesteśmy silni, podzieleni jesteśmy słabi.$B$BPrzynieś mi 8 dużych pancerzy skorpiad od opancerzonych skorpiad, a nagrodzę cię za przyswojenie tej mądrości.', 'Przynieś 8 dużych pancerzy skorpiad Kor\'ghanowi w Wiosce Sen\'jin.', '', '', '', '', '', '', 0),
(812, 'koKR', 'Potrzebne lekarstwo', '$N... zjawiasz się w samą porę. Mam tylko nadzieję, że pochwalę też twój pośpiech.$B$BByłem nieostrożny, walcząc z kilkoma jadoogonami w pobliżu, i jeden z nich głęboko mnie użądlił. Czuję, jak jego jad mnie osłabia, nawet teraz, gdy rozmawiamy. W tym tempie zostało mi może z godzinę życia. Ale jeśli mam przeżyć, potrzebuję twojej pomocy...$B$BKor\'ghan w Orgrimmarze wie, jak zrobić antidotum. Znajdź go... i pospiesz się, $N. Długo już nie wytrzymam. Powinien być w Szczelinie Cienia.', 'Znajdź Kor\'ghana w Orgrimmarze i zdobądź antidotum na jad jadoogona. Potem zanieś je Rhinagowi przy północno-zachodniej granicy Durotaru.', '', 'Wróć do Rhinaga nad Rzeką Południowej Furii na Pustkowiach.', '', '', '', '', 0),
(813, 'koKR', 'W poszukiwaniu antidotum', 'Jadoogony to jedne z najgroźniejszych skorpiad w Durotarze. Rhinag postąpił nierozsądnie, polując na nie bez antidotum, ale teraz reprymenda to ostatnie, czego mu trzeba.$B$BPrzynieś mi kilka woreczków z jadem jadoogonów, które kręcą się przy wejściu do Orgrimmaru, a zrobię dla niego antidotum.$B$BPospiesz się, $N. Ktoś z naszych potrzebuje twojej pomocy.', 'Przynieś 4 woreczki z jadem jadoogona Kor\'ghanowi w Orgrimmarze.', '', 'Wróć do Kor\'ghana w Szczelinie Cienia w Orgrimmarze.', '', '', '', '', 0),
(814, 'koKR', '', 'Gotuj i sprzątaj – nic innego nie robię!$B$BChcesz jeść, to przynieś mi więcej mięsa! Nie mam całego dnia, żeby polować i szykować żarcie dla tych wszystkich darmozjadów. Musisz się nauczyć pracować na swoje, jeśli chcesz, żeby cię traktowali na równi z innymi.$B$BPrzynieś mi trochę kawałów dziczyzny, jeśli chcesz się na coś przydać... albo jeśli nie chcesz umrzeć z głodu.', 'Przynieś 10 kawałów dziczyzny kucharzowi Torce w Brzytwogórze.', '', '', '', '', '', '', 0),
(815, 'koKR', 'Trzeba rozbić kilka jaj', 'Ech! Prawie zapomniałem, że muszę przygotować śniadanie.$B$B$N, ruszaj się i przynieś mi jaja biczoogonów. Potrzebuję przynajmniej trzech, żeby starczyło na jutrzejszy posiłek.$B$BKrwawoszpone biczoogony potrafią być zajadłe i najczęściej bronią swoich jaj do upadłego. Czasem zakopują je w ziemi za głęboko, żeby dało się je bezpiecznie wykopać, ale jak pójdziesz na Wyspy Echa, na południowy wschód od Wioski Sen\'jin, zwykle znajdziesz je na tych wyspach wszędzie.', 'Przynieś 3 jaja biczoogona kucharzowi Torce w Brzytwogórze.', '', 'Wróć do kucharza Torki w Durotarze.', '', '', '', '', 0),
(816, 'koKR', 'Zaginiony, lecz niezapomniany', '$N, proszę, pomożesz mi? Mój syn Kron wyruszył na polowanie kilka dni temu i wciąż nie wrócił. Poszedł na zachód, w stronę Pustkowi, polować na krokoliszki wzdłuż Rzeki Południowej Furii. Obawiam się najgorszego.$B$BBył silny, ale uparta duma zawsze pakowała go w kłopoty. Ostrzegałam go, że krokoliszki są potężne i zajadłe. Rozgniewał się i wybiegł wściekły.$B$BJeśli go nie znajdziesz, przynieś mi chociaż jakiś znak tego, co go spotkało... nawet jeśli będziesz $gmusiał:musiała; rozpruć brzuch każdego krokoliszka nad brzegami Południowej Furii.', 'Przynieś jakiś znak losu Krona Mishy Tor\'kren w gospodarstwie na północny zachód od Brzytwogóry.', '', 'Wróć do Mishy Tor\'kren na Farmie Tor\'kren w Durotarze.', '', '', '', '', 0),
(817, 'koKR', 'Praktyczna zdobycz', 'Wiele skór, których używamy, pochodzi z tygrysów z Durotaru, $N. Koce, zbroje, namioty: mamy mnóstwo powodów, by polować na te bestie, i równie wiele, by pozwalać im się mnożyć.$B$BNadszedł czas, by, że tak powiem, przerzedzić stado. Jest nas coraz więcej i nasze potrzeby zaczynają przerastać zapasy. Potrzebuję więcej skór, jeśli mam przygotować porządne wyroby dla naszego ludu.$B$BPrzynieś mi 4 futra tygrysów z Durotaru, a cię wynagrodzę. Znajdziesz je na wyspach na południe stąd.', 'Przynieś 4 futra tygrysa z Durotaru Vel\'rinowi Kłowi w Wiosce Sen\'jin.', '', 'Wróć do Vel\'rina Kła w Wiosce Sen\'jin w Durotarze.', '', '', '', '', 0),
(818, 'koKR', 'Duch rozpuszczalnika', 'Choć zawodzą mnie oczy, wciąż widzę dość jasno. Coraz częściej muszę się wspierać sztuką alchemii przy magii, która kiedyś przychodziła mi z łatwością. Ale nie chcę przyjąć ucznia – nigdy nie zgłosił się żaden troll ani ork, który byłby tego godzien.$B$BCzy ty jesteś $ggodzien:godna;? Tak, oczywiście, że jesteś... oczywiście, że tak ci się wydaje.$B$BPotrzebuję kilku rzeczy. Zdobędziesz je dla mnie?$B$BPotrzebuję nienaruszonych oczu makrur i fiolek ze śluzem pełzaczy. Zdobędziesz je z każdej makrury i każdego pełzacza w Durotarze. Wkrótce znów porozmawiamy.', 'Przynieś 4 nienaruszone oczy makrury i 8 fiolek śluzu pełzacza mistrzowi Vornalowi w Wiosce Sen\'jin.', '', 'Wróć do mistrza Vornala w Wiosce Sen\'jin w Durotarze.', '', '', '', '', 0),
(820, 'koKR', '', 'Naprawdę w twoim ciele mieszka duch siły – a może to było tylko szczęście, co?$B$BNa tym dziś polegają młodzi: na szczęściu... i na hojności potężniejszych od siebie. Niewielu zadaje sobie trud, by znaleźć własną ścieżkę. Zawsze tylko proszą o pomoc... zawsze nagroda, nigdy wyprawa. Na pewno z tobą będzie tak samo.$B$BAle jest nadzieja. Potrzebuję do mikstury jeszcze jednej rzeczy, $N: 8 pęków połyskliwego ziela. Rośnie na Grani Grzmotu, na północny zachód od Brzytwogóry.', 'Przynieś 8 pęków połyskliwego ziela mistrzowi Vornalowi w Wiosce Sen\'jin.', '', '', '', '', '', '', 0),
(823, 'koKR', 'Zamelduj się u Orgnila', 'My w Wiosce Sen\'jin mamy własne kłopoty i dziękujemy ci za pomoc. Ale wieści o Płonącym Ostrzu, które przynosisz, mogą oznaczać kłopoty dla wszystkich.$B$BW Brzytwogórze stacjonuje ork, Orgnil Blizna Duszy, który strzeże Durotaru przed takim złem jak Płonące Ostrze! Idź do Orgnila i opowiedz mu o naszym trudnym położeniu oraz o tym, czego $gdowiedziałeś:dowiedziałaś; się w Dolinie Prób. Będzie chciał o tym wiedzieć.$B$BBrzytwogóra leży na północy.', 'Porozmawiaj z Orgnilem Blizną Duszy w Brzytwogórze.', '', '', '', '', '', '', 0),
(825, 'koKR', 'Z wraku...', 'Jeden z moich najbardziej spostrzegawczych zwiadowców donosi, że wrak floty Proudmoore\'a wciąż leży u wybrzeży Durotaru, tuż na wschód od Twierdzy Tiragarde.$b$bNie jest tajemnicą, że ludzie w sojuszu z tymi plugawymi stworkami zwanymi gnomami mają rozległą wiedzę o mechanice. Musimy dokładnie poznać wszystkich naszych potencjalnych wrogów. A nasz lud także skorzysta na tej nowej wiedzy.$b$bPrzepłyń przez wrak, $n, i przynieś mi narzędzia Przymierza.', 'Gar\'Thok z Brzytwogóry chce, żebyś $gwydobył:wydobyła; 3 gnomie narzędzia z wraku u wybrzeża.', '', 'Wróć do Gar\'Thoka w Durotarze.', '', '', '', '', 0),
(826, 'koKR', 'Zalazane', 'Znachor Zalazane mieszka na Wyspach Echa na wschodzie. To wyspy, które kiedyś nazywaliśmy domem.$B$BStamtąd wysyła swoje trolle na stały ląd, by rzucały uroki na nasz lud i podporządkowywały mu coraz więcej z nas.$B$BTrzeba go powstrzymać.$B$BPokonaj Zalazanego i jego sługi – dawne trolle Mrocznej Włóczni, dla nas już stracone. Przynieś mi jego głowę, a będę wiedział, że jego złe rządy dobiegły końca.', 'Pokonaj Zalazanego.$B$BZabij 8 trolli wudu i 8 trolli pod złym urokiem.$B$BPrzynieś głowę Zalazanego Gadrinowi.', '', 'Wróć do mistrza Gadrina w Wiosce Sen\'jin w Durotarze.', '', '', '', '', 0),
(827, 'koKR', 'Skała Czaszki', '$N. Płonące Ostrze opanowało jaskinię na wschód od Orgrimmaru, zwaną Skałą Czaszki. W tej jaskini odprawiają plugawe rytuały i przypalają sobie ciała palącymi kołnierzami.$B$BSądzę, że nosząc te kołnierze, kultyści dostrajają się do demonicznej mocy. Ale żeby to potwierdzić, muszę zebrać kilka kołnierzy do zbadania.$B$BIdź do Skały Czaszki i zbierz palące kołnierze od kultystów, których tam znajdziesz. Przynieś mi je, a odkryję ich tajemnice.', 'Zbierz palące kołnierze od kultystów w Skale Czaszki.$B$BPrzynieś je Margozowi do jego obozu.', '', 'Wróć do Margoza w Durotarze.', '', '', '', '', 0),
(828, 'koKR', 'Margoz', 'Jeden z naszych szamanów, Margoz, wie więcej o zepsuciu Płonącego Ostrza. Mówi o jaskini w górach zwanej Skałą Czaszki – tuż pod Orgrimmarem! – w której ukrywa się duża banda kultystów Płonącego Ostrza.$B$BZanim pójdziesz do Skały Czaszki, porozmawiaj z Margozem. Jest mądry, a jego rady są cenione.$B$BObozuje na północnym wschodzie, między wybrzeżem a Parowem Suchego Koryta.$B$BPosłuchaj jego rad, ale cokolwiek powie Margoz, $N, i tak chcę, żebyś $gzmiażdżył:zmiażdżyła; tych kultystów!', 'Porozmawiaj z Margozem.', '', '', '', '', '', '', 0),
(829, 'koKR', 'Neeru Płomienne Ostrze', 'Palące kołnierze, które mi $gprzyniosłeś:przyniosłaś;, to potężne, demoniczne narzędzia. Obawiam się, że odkrycie ich pochodzenia przekracza moje umiejętności szamana. Potrzebujemy czarnoksiężnika, by je zbadał.$B$BZanieś palący kołnierz Neeru Płomiennemu Ostrzu. Choć jest wprawnym czarnoksiężnikiem, twierdzi, że używa swoich mocy przeciw demonom, a jego badania nad okultyzmem są nieszkodliwe. Prawda to czy nie, możemy potrzebować jego pomocy przeciw demonicznemu kultowi w Durotarze.$B$BNeeru znajdziesz w Orgrimmarze, w Szczelinie Cienia.', 'Zanieś przykładowy kołnierz Neeru Płomiennemu Ostrzu w Orgrimmarze.', '', '', '', '', '', '', 0),
(830, 'koKR', 'Rozkazy admirała', 'Otwierasz starą, zniszczoną kopertę i znajdujesz dokument o urzędowym wyglądzie. Rozpoznajesz pieczęć admirała Proudmoore\'a.$b$bWygląda to na coś ważnego. Może Gar\'Thok, dowódca Brzytwogóry, chciałby poznać te informacje.', 'Zanieś rozkazy admirała Proudmoore\'a Gar\'Thokowi w Brzytwogórze.', '', '', '', '', '', '', 0),
(831, 'koKR', 'Rozkazy admirała', 'Ludziom nie można ufać. Walczyliśmy u ich boku z ciężkim sercem, wiedząc, że pewnego dnia nas zdradzą.$b$bŚmierć admirała Proudmoore\'a nie wystarczyła, by położyć kres jego podstępnej spuściźnie. Ta ludzka hołota miała jego plany dobrze przygotowane na długo przed tym, jak zginął.$b$bWygląda na to, że jego władza nie umrze nawet razem z Benedictem. Kto wie, ile czasu minie, zanim kolejne fale ludzi Proudmoore\'a wylądują na naszych brzegach.$b$bMusimy natychmiast dostarczyć te rozkazy Vol\'jinowi w Orgrimmarze! Znajdziesz go w komnacie Thralla.', 'Dostarcz rozkazy admirała Proudmoore\'a Vol\'jinowi w komnacie Thralla w Orgrimmarze.', '', '', '', '', '', '', 0),
(832, 'koKR', 'Płonące cienie', '<Z wisiora płyną słowa, które docierają prosto do twojego umysłu.>$B$BGazz\'uz?$B$BGazz\'uz... melduj!$B$BDoszły nas wieści, że odkryto cię w Skale Czaszki. Musisz przygotować się na atak!$B$BGazz\'uz, rozkazuję ci mówić! Mów, albo dopilnuję, by Neeru Płomienne Ostrze dowiedział się o twojej obecności, a wtedy spadnie na ciebie szybko i bezlitośnie.$B$BNie wystawiaj swoich umiejętności na próbę przeciw Neeru...$B$B...Gazz\'uz, jesteś tam...?', 'Zanieś to oko Neeru Płomiennemu Ostrzu w Orgrimmarze.', '', '', '', '', '', '', 0),
(834, 'koKR', 'Wiatry na pustyni', 'Jestem Rezlak, jeden z chłopaków Gazola. Szef przysłał mnie, żebym pomógł orkom tu, w Durotarze. Wszystko szło dobrze, tylko te karawany! Nie da się ich upilnować! Trochę mi to utrudnia robotę, wiesz?$b$bOstatnią dostawę – obiecywali, że dotrze! – porwały harpie Pylistego Wiatru z... jak to było... Kanionu Ostrego Wiatru?$b$bMuszę mieć te zapasy, bo inaczej nic nie zrobię! Idź wielkim kanionem na południe, a znajdziesz wąwóz wcięty w jego zachodnią i wschodnią ścianę.', 'Odzyskaj 5 worków z zapasami i zanieś je Rezlakowi niedaleko Orgrimmaru.', '', 'Wróć do Rezlaka w Durotarze.', '', '', '', '', 0),
(835, 'koKR', 'Zabezpieczenie szlaków', 'Gazol powiedział mi kiedyś: „Rezlak. Jest w życiu jedna rzecz, którą musisz wiedzieć: jak chcesz, żeby coś było dobrze zrobione, zrób to sam”.$b$bNie mogę dalej tracić wszystkich karawan, więc biorę sprawy w swoje ręce. Parów Suchego Koryta leży we wschodniej części Kanionu Ostrego Wiatru. Jeśli zabijemy tam wszystkie harpie, szlaki będą bezpieczne.$b$bOczywiście Gazol nauczył mnie jeszcze jednego: „Za odpowiednią cenę da się załatwić wszystko”. To jak, pomożesz mi, $n?', 'Zabij 12 dzikusek Pylistego Wiatru i 8 wiedźm burzy Pylistego Wiatru dla Rezlaka niedaleko Parowu Suchego Koryta.', '', 'Wróć do Rezlaka w Durotarze.', '', '', '', '', 0),
(837, 'koKR', 'Wtargnięcie', 'Gdy tu przybyliśmy, kolcozwierze z Brzytwogrzywych władały dużą częścią tych ziem i były dla nas cierniem w boku. Dzięki naszym wysiłkom wyparliśmy większość z nich, ale w niektórych miejscach wciąż mocno się trzymają.$b$bTo jednak trwa już zbyt długo. Dla naszego własnego bezpieczeństwa nie możemy pozwolić Brzytwogrzywym utrzymać się na naszych ziemiach. Ich obozy znajdziesz na zachód stąd. Szukaj ciernistych zarośli, a znajdziesz i ich. Dziś wypędzimy ich z Durotaru, jutro może z całego Kalimdoru.', 'Zabij 4 kolcozwierze z Brzytwogrzywych, 4 zwiadowców Brzytwogrzywych, 4 pyłobiegaczki Brzytwogrzywych i 4 strażników bitewnych Brzytwogrzywych dla Gar\'Thoka w Brzytwogórze.', '', 'Wróć do Gar\'Thoka w Durotarze.', '', '', '', '', 0),
(840, 'koKR', 'Poborowy Hordy', 'Hmm, wyglądasz na $gsilnego:silną;.$B$BSłuchaj, mój dobry przyjaciel Kargal potrzebuje nowych rekrutów do służby na Pustkowiach. Wiem, że chcesz dobrze służyć Hordzie. No to masz okazję.$B$BZanieś ten list werbunkowy Kargalowi i zobacz, czy go podpisze.', 'Idź zachodnią drogą z Brzytwogóry na Pustkowia, przez most.$B$BZatrzymaj się przy orczej placówce za mostem.$B$BOddaj swój list werbunkowy Kargalowi Bliźnie Wojny w placówce na Pustkowiach.', '', '', '', '', '', '', 0),
(842, 'koKR', 'Pobór na Rozdroże', 'Zanieś ten podpisany list werbunkowy na Rozdroże.$B$BDowodzi tam Sergra Ciemny Cierń, niech ją licho. To wredna szamanka, która zagada cię na śmierć, zanim pozwoli ci zrobić coś pożytecznego. Thrall jest przekonany, że jest w niej coś wyjątkowego, ale ja nie jestem tego pewien.$B$BMusisz to ocenić $gsam:sama;, szczeniaku...', 'Idź zachodnią drogą od Wysuniętego posterunku Kargala.$B$BNa skrzyżowaniu w kształcie litery T skręć w lewo i idź drogą na południe.$B$BZnajdź Sergrę Ciemny Cierń na skrzyżowaniu dróg na Rozdrożu.', '', '', '', '', '', '', 0),
(924, 'koKR', 'Demoniczne Nasiono', 'Demoniczne Nasiono to potężne narzędzie Płonącego Legionu. Spoczywa w jaskini na Szczycie Upiornej Mgły, nad demonicznym ołtarzem ognia.$B$BPrzygotowałem kamienie mocy, które umieszczone w pobliżu Nasiona przerwą jego więź z Legionem.$B$BWeź kamień ze stołu i zanieś go do ołtarza ognia na Szczycie Upiornej Mgły. Idź na zachód, a gdy droga się rozwidli – na północ. Szczyt będzie po twojej lewej. Najbezpieczniej wspiąć się na górę od północnej strony.$B$BI pospiesz się – moc kamienia z czasem sama się wyczerpie.', 'Weź wadliwy kamień mocy. Zanieś go do Ołtarza Ognia, zanim kamień się wyczerpie, a potem wróć do Ak\'Zelotha.', '', 'Wróć do Ak\'Zelotha na Pustkowiach.', 'Zniszcz Demoniczne Nasiono', '', '', '', 0),
(926, 'koKR', 'Wadliwy kamień mocy', '', '', '', '', '', '', '', '', 0),
(1066, 'koKR', 'Krew niewinnych', 'Stworzę toksynę, która wysączy ze spółki Gitgeszeft skłonność do przemocy i uczyni jej ludzi słabymi i potulnymi. To powinno rozwiązać problem Hordy w Szponogłazach, nieprawdaż?$B$BLecz do stworzenia toksyny potrzebuję krwi niewinnych, a to składnik trudny do zdobycia.$B$BNa szczęście Syndykat, banda ludzkich rozbójników z tej okolicy, zatrudnia magów cienia... a ci magowie zbierają niewinną krew do własnych, podejrzanych celów.$B$BMagów cienia z Syndykatu znajdziesz w Twierdzy Durnhold na południowym wschodzie.', 'Przynieś 5 fiolek niewinnej krwi aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(1462, 'koKR', 'Sapta ziemi', '', 'Porozmawiaj z jasnowidzką Kruczym Piórem, aby otrzymać kolejną saptę ziemi.', '', '', '', '', '', '', 0),
(1463, 'koKR', 'Sapta ziemi', '', 'Porozmawiaj z Canagą Przywoływaczem Ziemi, aby otrzymać kolejną saptę ziemi.', '', '', '', '', '', '', 0),
(1464, 'koKR', 'Sapta ognia', '', 'Porozmawiaj z Telfem Joolamem, aby otrzymać kolejną saptę ognia.', '', '', '', '', '', '', 0),
(1485, 'koKR', 'Plugawe chowańce', 'Czarnoksiężnicy, którzy byli przed nami, zasłużyli sobie na nieufność Hordy, i choć się nas toleruje, nikt nas nie kocha.$b$bNie zbliżyło to jednak czarnoksiężników do siebie – wielu woli żyć w odosobnieniu i parać się magią w samotności. Nie zamierzam prowadzić cię tą czy inną ścieżką, pomogę ci jedynie dojrzeć.$b$bZanim nauczę cię sztuki przyzywania, przynieś mi sześć głów plugawych chowańców z jaskini na północnym wschodzie.', 'Przynieś Ruzanowi 6 głów plugawych chowańców.', '', 'Wróć do Ruzana w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(1499, 'koKR', 'Plugawe chowańce', 'Zureetha wysyła nowicjuszy takich jak ty, żeby pomogli przetrzebić stwory w jaskini niedaleko miejsca, gdzie $gwalczyłeś:walczyłaś; z plugawymi chowańcami.$b$bMyślę, że dobrze ci zrobi, jeśli nabierzesz doświadczenia, pomagając jej. Koniecznie powiedz jej, że $gpomogłeś:pomogłaś; uporać się z chochlikami – pewnie ma dla ciebie jakąś nagrodę.', 'Porozmawiaj z Zureethą Dalekowzroczną.', '', '', '', '', '', '', 0),
(1505, 'koKR', 'Weteran Uzzek', 'Horda czci swoich wojowników, bo ich siła nie podlega dyskusji. Ale prawdziwie wielcy wojownicy są też pilnymi uczniami.$B$BOdszukaj Uzzeka. To weteran wielu bitew, który teraz uczy młodych wojowników sztuki walki. Znajdziesz go na południe od Wysuniętego posterunku, orkowego garnizonu na granicy Pustkowi i Durotaru.', 'Porozmawiaj z Uzzekiem na Wysuniętym posterunku na Pustkowiach.', '', '', '', '', '', '', 0),
(1506, 'koKR', 'Wezwanie od Gan\'rula', 'Hej, ty. $n, zgadza się?$b$bMam nadzieję, że nie masz napiętego grafiku, bo Gan\'rul chce cię natychmiast widzieć. Znajdziesz go u starszych czarnoksiężników w Szczelinie Cienia.$b$bZ tego, co wiem o Gan\'rulu, jego wezwanie oznacza albo coś bardzo dobrego, albo coś bardzo złego.', 'Porozmawiaj z Gan\'rulem Krwawe Oko w Orgrimmarze.', '', '', '', '', '', '', 0),
(1522, 'koKR', 'Zew ognia', 'Ogień jest z tobą. Widzę, że jesteś już $gsilny:silna; w drogach ziemi, i myślę, że jesteś $ggotów:gotowa; porozmawiać z Kranalem.$B$BKranal mieszka na północ od Rozdroża na Pustkowiach. Jest potężny w drogach żywiołów i może nauczyć cię dróg ognia... jeśli uważasz, że jesteś $ggotów:gotowa;.$B$BŁatwo go znaleźć, tylko nie zapuszczaj się za daleko – jak pójdziesz za daleko, trafisz na ziemie elfów.', 'Odszukaj Kranala Fissa na Pustkowiach.', '', '', '', '', '', '', 0),
(1523, 'koKR', 'Zew ognia', 'Wiele czasu minęło od twojej ostatniej próby, $N. Dotąd $gwykazywałeś:wykazywałaś; cierpliwość w nauce, ale nadszedł czas, byś $gpoznał:poznała; więcej. Nadszedł czas, byś $gpoznał:poznała; zniszczenie... i chaos. Żywioł ognia może stać się twój, jeśli pojmiesz go i będziesz $ggotów:gotowa; za to zapłacić.$B$BOdszukaj Kranala Fissa na Pustkowiach. Mieszka w małym domostwie na północ od Rozdroża, ale uważaj – jeśli dotrzesz do ziem nocnych elfów, $gzaszedłeś:zaszłaś; za daleko.', 'Odszukaj Kranala Fissa na Pustkowiach.', '', '', '', '', '', '', 0),
(1524, 'koKR', 'Zew ognia', 'Masz dość mocy, by władać totemem ognia, ale to nie znaczy, że jesteś $ggotów:gotowa;.$B$BWzdłuż Rzeki Południowej Furii w Durotarze, tuż przed Wielkim Morzem, biegnie ukryty szlak na jeden z najwyższych szczytów tej krainy. Wespnij się na samą górę, a znajdziesz jedną z naszych świętych kaplic, której strzeże Telf Joolam – Kaplicę Uśpionego Płomienia.$B$BZanieś mu tę pochodnię – jest znakiem, że próbujesz okiełznać ogień. Zapal ją w palenisku przy kaplicy i przynieś mi ją płonącą, a dopilnuję, byś $gotrzymał:otrzymała; totem ognia.', 'Zanieś pochodnię uśpionego płomienia Telfowi Joolamowi w Durotarze.', '', '', '', '', '', '', 0),
(1525, 'koKR', 'Zew ognia', 'Ale nie $gprzyszedłeś:przyszłaś; tu na lekcję historii, prawda? $GPrzyszedłeś:Przyszłaś; po Wieczny Płomień i totem ognia.$B$BPierwszym krokiem jest przyrządzenie sapty, która zwiąże cię z płomieniem.$B$BMogę przygotować dla ciebie saptę ognia, jeśli przyniesiesz mi dwie rzeczy. Pierwsza to ognista smoła – pospolita rzecz, którą zwykle noszą przy sobie czarownicy Brzytwogrzywych we wschodniej części Pustkowi.$B$BZdobycie drugiej będzie bardziej niebezpieczne: to sakiewka na składniki jednego z kultystów Płonącego Ostrza. Znajdziesz ich w jaskini nad wąwozami na północny wschód od Brzytwogóry.', 'Przynieś 1 ognistą smołę i 1 sakiewkę na składniki Telfowi Joolamowi w Durotarze.', '', 'Wróć do Telfa Joolama w Kaplicy Uśpionego Płomienia w Durotarze.', '', '', '', '', 0),
(1526, 'koKR', 'Zew ognia', 'Sapta ognia jest gotowa. Nadszedł czas, byś $gstanął:stanęła; twarzą w twarz z płomieniem. Użyj sapty przy kaplicy i wejdź na szczyt góry, by zmierzyć się z czekającą tam manifestacją. Nie zaatakuje, dopóki nie będziesz $ggotów:gotowa;, ale zorientuje się, że ją widzisz.$B$BZgładź ją szybko, $N, bo im dłużej będziesz z tym zwlekać, tym potężniejsza się stanie. Gdy ją pokonasz, umieść jej żarzące się węgielki w palenisku i zapal pochodnię.', 'Pokonaj pomniejszą manifestację ognia i umieść żarzący się węgielek w palenisku na szczycie Kaplicy Uśpionego Płomienia.', '', '', '', '', '', '', 0),
(1527, 'koKR', 'Zew ognia', 'Mocno ściskając pochodnię, odwracasz się od paleniska i spoglądasz na Durotar. Czujesz, jak podniecenie szarpie twoim duchem, a wiatr przybiera na sile i zmusza płomień do gwałtownego tańca.$B$BRuszasz ścieżką z powrotem w stronę Pustkowi, by odnaleźć Kranala Fissa.', 'Zanieś pochodnię wiecznego płomienia Kranalowi Fissowi na Pustkowiach.', '', '', '', '', '', '', 0),
(1528, 'koKR', 'Zew wody', 'W twojej przyszłości jest woda. Widzę, że jesteś już $gsilny:silna; w drogach ognia, i myślę, że jesteś $ggotów:gotowa; porozmawiać z Islen.$B$BIslen mieszka na wybrzeżu Pustkowi. Jak pójdziesz na południe wzdłuż Rzeki Południowej Furii, nie przegapisz jej – wypatruj wielkiego rekina! Jest potężna w drogach żywiołów i może nauczyć cię dróg wody... jeśli uważasz, że jesteś $ggotów:gotowa;.$B$BŁatwo ją znaleźć, tylko nie zapuszczaj się za daleko na południe – mieszka zaraz za Zapadką.', 'Odszukaj Islen Wodowieszczkę na Pustkowiach.', '', '', '', '', '', '', 0),
(1529, 'koKR', 'Zew wody', 'Wiele czasu minęło od twojej ostatniej próby, $N. Dotąd $gwykazywałeś:wykazywałaś; cierpliwość w nauce, ale nadszedł czas, byś $gpoznał:poznała; więcej. Nadszedł czas, byś $gpoznał:poznała; czystość wody.$B$BOdszukaj Islen Wodowieszczkę na Pustkowiach. Mieszka na wschodnim wybrzeżu, na południe od Rzeki Południowej Furii i Zapadki. Znajdziesz ją w jej chacie rybackiej. Powodzenia, $N.', 'Odszukaj Islen Wodowieszczkę na Pustkowiach.', '', '', '', '', '', '', 0),
(1839, 'koKR', 'Ula\'elek i brutalne rękawice pancerne', 'Trollowy kowal Ula\'elek wykuje dla ciebie brutalne rękawice pancerne. Mieszka w Durotarze, w Wiosce Sen\'jin, razem ze swoimi pobratymcami z Mrocznej Włóczni, i czeka na twoje przybycie.', 'Porozmawiaj z Ula\'elekiem w Durotarze.', '', '', '', '', '', '', 0),
(1842, 'koKR', 'Kopyta satyrów', 'Mogę zrobić dla ciebie parę brutalnych rękawic pancernych, a wielka magia w nich zamieszka. Ale najpierw musisz tę magię zebrać i mi ją przynieść.$B$BSatyry żyją w północno-wschodniej części Jesionowej Kniei, bo przyciąga je moc lasu. Karmią się jego czystością, wysysając ją i wypaczając. Te satyry, które wyssały najwięcej magii Jesionowej Kniei, poznasz po spuchniętych, nierozszczepionych kopytach.$B$BTe kopyta kryją wielką moc. Potrzebuję ich, żeby wykuć twoje rękawice.', 'Przynieś 7 nierozszczepionych kopyt satyra Ula\'elekowi w Wiosce Sen\'jin w Durotarze.', '', 'Wróć do Ula\'eleka na Wybrzeżu Mrocznych Włóczni w Durotarze.', '', '', '', '', 0),
(1843, 'koKR', 'Brutalne rękawice pancerne', '', '', '', '', '', '', '', '', 0),
(1859, 'koKR', 'Therzok', 'Ścisz głos, $n. Tak, znam twoje imię. Kazano mi wypatrywać orka pasującego do twojego opisu.$b$bZ tego, co o tobie słyszeliśmy, radzisz sobie w walce i nie masz nic przeciwko odrobinie podstępu od czasu do czasu.$b$bMam rację?$b$bTak czy inaczej, $gpowinieneś:powinnaś; odwiedzić Therzoka w Orgrimmarze. Ma dla ciebie propozycję.', 'Porozmawiaj z Therzokiem w Szczelinie Cienia w Orgrimmarze.', '', '', '', '', '', '', 0),
(1881, 'koKR', 'Porozmawiaj z Anastasią', '$N, Anastasia Hartwell ma zadanie dla kogoś o twoich talentach. Porozmawiaj z nią w Dzielnicy Magów Podmiasta i przygotuj się na swoje pierwsze zadanie dla magów Porzuconych.', 'Porozmawiaj z Anastasią Hartwell.', '', '', '', '', '', '', 0),
(1883, 'koKR', 'Porozmawiaj z Un\'Thuwą', 'Un\'Thuwa, plemienny mag z Wioski Sen\'jin, wyczuwa zaburzenie w prądach magii Durotaru i prosi o pomoc. Porozmawiaj z Un\'Thuwą i zrób, co możesz, by mu pomóc.$B$BZrób to, a z czasem odkryte zostaną przed tobą kolejne tajemnice.', 'Porozmawiaj z Un\'Thuwą.', '', '', '', '', '', '', 0),
(1884, 'koKR', 'Stosy juju', 'Czarnoksiężnik Zalazane z Wysp Echa zakłócił naturalny przepływ magii w Durotarze. Robi to za pomocą skażonych fetyszy – stosów juju, które rozmieścił wśród swoich chat na największej z Wysp Echa.$B$BTe stosy wypaczają naszą dziką zwierzynę i dają moc czarnoksiężnikom i piekielnym stworom, które czają się w mrocznych zakątkach tej krainy.$B$BMusisz zniszczyć stosy juju, $N, zanim przepływ magii zmieni się na zawsze.', 'Zniszcz 4 stosy juju, a następnie wróć do Un\'Thuwy w Wiosce Sen\'jin.', '', 'Wróć do Un\'Thuwy na Wybrzeżu Mrocznych Włóczni w Durotarze.', 'Zniszczone stosy juju', '', '', '', 0),
(1959, 'koKR', 'Zamelduj się u Anastasii', 'Magowie z Podmiasta wykryli w mieście zakłócenie magii i wezwali magów Hordy do zbadania sprawy.$B$BWięcej powie ci Anastasia Hartwell. Porozmawiaj z nią w Dzielnicy Magów w Podmieście.', 'Porozmawiaj z Anastasią Hartwell.', '', '', '', '', '', '', 0),
(2161, 'koKR', 'Brzemię peona', 'Przepraszam? Możesz mi pomóc?$B$BMam tu ładunek jedzenia. Szedłem drogą i stawiłem czoła skorpiadom, pająkom i jeszcze gorszym paskudom! Przyniosłem jedzenie do Doliny Prób, bo myślałem, że go potrzebują, a ja lubię pomagać. Ale oni wcale nie potrzebują jedzenia! Teraz muszę zanieść je z powrotem do Brzytwogóry, a boję się tych wszystkich bestii po drodze...$B$BZaniesiesz je za mnie? Jestem tylko peonem, ale ty jesteś $gbohaterem:bohaterką;. Niczego się nie boisz!$B$BZanieś je karczmarzowi Groskowi do gospody w Brzytwogórze. Dziękuję!', 'Zanieś brzemię Ukora karczmarzowi Groskowi w Brzytwogórze.', '', '', '', '', '', '', 0),
(2380, 'koKR', 'Do Orgrimmaru!', 'Mistrzem skradania i podstępu to ty nie jesteś, ale to wszystko może się zmienić i się zmieni. Najwyraźniej swoimi marnymi umiejętnościami $gzrobiłeś:zrobiłaś; wrażenie na tych, którzy tu rządzą, bo wielki Shenthul poprosił o ciebie po imieniu.$B$BIdź drogą na północ stąd do Orgrimmaru i porozmawiaj z Shenthulem w Szczelinie Cienia.$B', 'Porozmawiaj z Shenthulem w Szczelinie Cienia w Orgrimmarze.', '', '', '', '', '', '', 0),
(2383, 'koKR', 'Prosty pergamin', 'Ach, gdy cię nie było, przyszedł do ciebie pergamin, $N.$B$BPrzeczytaj go, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłał go nauczyciel wojowników Frang. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;. Znajdziesz go przed Norą, gdzie chowa się w cieniu.', 'Przeczytaj prosty pergamin i porozmawiaj z Frangiem w Dolinie Prób.', '', '', '', '', '', '', 0),
(2934, 'koKR', 'Nieuszkodzony gruczoł jadowy', 'Muszę mieć świeżą próbkę jadu, który mi $gprzyniosłeś:przyniosłaś;. Pająki, od których go zebrano, muszą żyć w Zaziemiu – poluj na nie, aż znajdziesz nieuszkodzony gruczoł jadowy, i przynieś mi go. Wiele pająków znajdziesz w pobliżu trollowego miasta Shadra\'Alor.$B$BNie zwlekaj, $N, bo gruczoł musi być świeży, gdy mi go dostarczysz.', 'Przynieś nieuszkodzony gruczoł jadowy aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(2935, 'koKR', 'Zasięgnij rady mistrza Gadrina', 'Jad strażników lęgowiska nie był tak silny jak ten, który $gprzyniosłeś:przyniosłaś; na początku. Musiał pochodzić od innego pająka.$B$BChcę świeżą próbkę tamtego jadu. Aby ustalić, skąd pochodzi, musisz poradzić się trolla, który dobrze zna Suchokorych – mistrza Gadrina z Wioski Sen\'jin. Udaj się do Durotaru i porozmawiaj z Gadrinem. Przy odrobinie szczęścia będzie wiedział, skąd Suchokorzy biorą swój jad.', 'Porozmawiaj z mistrzem Gadrinem w Wiosce Sen\'jin.', '', '', '', '', '', '', 0),
(2936, 'koKR', 'Bogini pająków', 'Suchokorzy czczą boginię pająków i to od niej zbierają najsilniejszy jad. Więc jeśli chcesz jadu, musisz przyzwać ich boginię!$B$BAby to zrobić, musisz znać jej prawdziwe imię, a to imię jest wyryte na tabliczce ukrytej w Tanaris, w trollowym mieście Zul\'Farrak, w grobowcu strzeżonym przez Thekę Męczennika.$B$BPokonaj Thekę, odnajdź jego tabliczkę i odczytaj ją, by poznać imię bogini pająków. Gdy już je poznasz, wróć do mnie.', 'Odczytaj tabliczkę Theki, by poznać imię bogini pająków Suchokorych, a następnie wróć do mistrza Gadrina.', 'Poznaj imię bogini pająków', 'Wróć do mistrza Gadrina w Wiosce Sen\'jin w Durotarze.', '', '', '', '', 0),
(2937, 'koKR', 'Przyzwanie Shadry', 'Weź ten pergamin i odczytaj go przy ołtarzu w Shadra\'Alor, w głębi krainy Suchokorych w Zaziemiu. To przyzwie Shadrę, boginię pająków.', 'Pokonaj Shadrę przy ołtarzu w Shadra\'Alor, a następnie zanieś jej jad aptekarzowi Lydonowi w Smolnym Młynie.', '', 'Wróć do aptekarza Lydona w Smolnym Młynie w Międzygórzu.', '', '', '', '', 0),
(2983, 'koKR', 'Zew ognia', 'Minęło trochę czasu od twojej ostatniej próby, $N. Jak dotąd $gbyłeś:byłaś; $gcierpliwy:cierpliwa; w nauce, ale pora, byś $gpoznał:poznała; większe moce... pora, byś $gpoznał:poznała; prawdziwą moc. Żywioł ognia będzie twój, jeśli jesteś $ggotów:gotowa; za niego zapłacić.$B$BOdszukaj Kranala Fissa na Pustkowiach. Mieszka w małej chacie na północ od Rozdroża, ale uważaj – jeśli dotrzesz do przeklętych ziem nocnych elfów, to znaczy, że $gzaszedłeś:zaszłaś; o wiele za daleko.', 'Odszukaj Kranala Fissa na Pustkowiach.', '', '', '', '', '', '', 0),
(2984, 'koKR', 'Zew ognia', 'Wiele czasu minęło od twojej ostatniej próby, $N. Dotąd $gwykazywałeś:wykazywałaś; cierpliwość w nauce, ale nadszedł czas, byś $gpoznał:poznała; więcej. Nadszedł czas, byś $gpoznał:poznała; zniszczenie... i chaos. Żywioł ognia może stać się twój, jeśli pojmiesz go i będziesz $ggotów:gotowa; za to zapłacić.$B$BOdszukaj Kranala Fissa na Pustkowiach. Mieszka w małym domostwie na północ od Rozdroża, ale uważaj – jeśli dotrzesz do ziem nocnych elfów, $gzaszedłeś:zaszłaś; za daleko.', 'Odszukaj Kranala Fissa na Pustkowiach.', '', '', '', '', '', '', 0),
(2985, 'koKR', 'Zew wody', 'Wyglądasz na $ggotowego:gotową; do kolejnej próby, $N. $GByłeś:Byłaś; $gcierpliwy:cierpliwa; w nauce, ale nadszedł czas, byś $gdowiedział:dowiedziała; się więcej. Nadszedł czas, byś $gpoznał:poznała; czystość wody.$B$BOdszukaj Islen Wodowieszczkę na Pustkowiach. Mieszka na wschodnim wybrzeżu, na południe od Rzeki Południowej Furii i Zapadki. Znajdziesz ją w jej rybackiej chacie. Powodzenia, $N.', 'Odszukaj Islen Wodowieszczkę na Pustkowiach.', '', '', '', '', '', '', 0),
(2986, 'koKR', 'Zew wody', 'Wiele czasu minęło od twojej ostatniej próby, $N. Dotąd $gwykazywałeś:wykazywałaś; cierpliwość w nauce, ale nadszedł czas, byś $gpoznał:poznała; więcej. Nadszedł czas, byś $gpoznał:poznała; czystość wody.$B$BOdszukaj Islen Wodowieszczkę na Pustkowiach. Mieszka na wschodnim wybrzeżu, na południe od Rzeki Południowej Furii i Zapadki. Znajdziesz ją w jej chacie rybackiej. Powodzenia, $N.', 'Odszukaj Islen Wodowieszczkę na Pustkowiach.', '', '', '', '', '', '', 0),
(3065, 'koKR', 'Prosta tabliczka', 'Ach, gdy cię nie było, przyszedł do ciebie pergamin, $N.$B$BPrzeczytaj go, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłał go nauczyciel wojowników Frang. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;. Znajdziesz go przed Norą, gdzie chowa się w cieniu.', 'Przeczytaj prostą tabliczkę i porozmawiaj z Frangiem w Dolinie Prób.', '', '', '', '', '', '', 0),
(3082, 'koKR', 'Ryta tabliczka', 'Ach, gdy cię nie było, przyszła do ciebie tabliczka, $N.$B$BPrzeczytaj ją, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłała ją nauczycielka łowców Jen\'shan. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Porozmawiaj z Jen\'shan w Dolinie Prób.', '', '', '', '', '', '', 0),
(3083, 'koKR', 'Zaszyfrowana tabliczka', 'Ach, gdy cię nie było, przyszła do ciebie tabliczka, $N.$B$BPrzeczytaj ją, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłał ją nauczyciel łotrzyków Rwag. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj zaszyfrowaną tabliczkę i porozmawiaj z Rwagiem w Dolinie Prób.', '', '', '', '', '', '', 0),
(3084, 'koKR', 'Tabliczka z wyrytymi runami', 'Ach, gdy cię nie było, przyszła do ciebie tabliczka, $N.$B$BPrzeczytaj ją, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłała ją nauczycielka szamanów Shikrik. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Porozmawiaj z Shikrik w Dolinie Prób.', '', '', '', '', '', '', 0),
(3085, 'koKR', 'Uświęcona tabliczka', 'Ach, gdy cię nie było, przyszła do ciebie tabliczka, $N.$B$BPrzeczytaj ją, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłał ją nauczyciel kapłanów Ken\'jai. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj uświęconą tabliczkę i porozmawiaj z Ken\'jaiem przed Norą w Dolinie Prób.', '', '', '', '', '', '', 0),
(3086, 'koKR', 'Tabliczka z glifami', 'Ach, gdy cię nie było, przyszła do ciebie tabliczka, $N.$B$BPrzeczytaj ją, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłała ją nauczycielka magów Mai\'ah. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj tabliczkę z glifami i porozmawiaj z Mai\'ah przy wejściu do Nory w Dolinie Prób.', '', '', '', '', '', '', 0),
(3087, 'koKR', 'Wytrawiony pergamin', 'Ach, gdy cię nie było, przyszedł do ciebie pergamin, $N.$B$BPrzeczytaj go, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłała go nauczycielka łowców Jen\'shan. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj wytrawiony pergamin i porozmawiaj z Jen\'shan w Dolinie Prób.', '', '', '', '', '', '', 0),
(3088, 'koKR', 'Zaszyfrowany pergamin', 'Ach, gdy cię nie było, przyszedł do ciebie pergamin, $N.$B$BPrzeczytaj go, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłał go nauczyciel łotrzyków Rwag. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj zaszyfrowany pergamin i porozmawiaj z Rwagiem w Dolinie Prób.', '', '', '', '', '', '', 0),
(3089, 'koKR', 'Pergamin z runami', 'Ach, gdy cię nie było, przyszedł do ciebie pergamin, $N.$B$BPrzeczytaj go, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłała go nauczycielka szamanów Shikrik. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj pergamin z runami i porozmawiaj z Shikrik w Dolinie Prób.', '', '', '', '', '', '', 0),
(3090, 'koKR', 'Skażony pergamin', 'Ach, gdy cię nie było, przyszedł do ciebie pergamin, $N.$B$BZwykle unikam czarnoksiężników, jak tylko mogę, ale myślę, że $gpowinieneś:powinnaś; go przeczytać, kiedy znajdziesz chwilę. Jeśli się nie mylę, przysłał go twój nowo przydzielony nauczyciel Nartok. Chce z tobą pomówić, gdy będziesz $ggotów:gotowa;.', 'Przeczytaj skażony pergamin i porozmawiaj z Nartokiem w Norze w Dolinie Prób.', '', '', '', '', '', '', 0),
(4402, 'koKR', 'Niespodzianka z kaktusowego jabłka Galgara', 'Ależ tu gorąco w tej Dolinie Prób.$B$B<Galgar ociera czoło.>$B$BGdybym tylko miał parę kaktusowych jabłek, zrobiłbym moją słynną niespodziankę z kaktusowego jabłka! Nic tak szybko nie chłodzi jak kawałek tego pysznego przysmaku.$B$BWiesz co, $N? Jeśli przyniesiesz mi 6 kaktusowych jabłek, zrobię ci kilka porcji niespodzianki z kaktusowego jabłka na drogę. Jeśli cię to interesuje, kaktusowe jabłka rosną przy tutejszych kaktusach.', 'Przynieś Galgarowi 6 kaktusowych jabłek. Pamiętasz, jak mówił, że można je znaleźć przy kaktusach.', '', 'Wróć do Galgara w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(4641, 'koKR', 'Twoje miejsce w świecie', 'Wreszcie $gdorosłeś:dorosłaś;, $N... dość, by walczyć w imię Hordy. By zdobywać nowe ziemie ku chwale wodza.$B$BTak...$B$B<Kaltunk mierzy cię wzrokiem.>$B$BNadasz się.$B$BZ pewnością $gchciałbyś:chciałabyś; znaleźć wielkiego smoka albo demona i udusić go gołymi rękami, ale może rozsądniej byłoby zacząć od czegoś mniej... niebezpiecznego.$B$B<Kaltunk się śmieje.>$B$BZamelduj się u Gorneka, powinien przydzielić ci zadanie lepiej dopasowane do kogoś tak młodego jak ty. Znajdziesz Gorneka w Norze, na zachodzie.$B', 'Porozmawiaj z Gornekiem. Pamiętasz, że Kaltunk zaznaczył ci na mapie, gdzie go szukać, i wspomniał, że Gornek przebywa w Norze, budynku na zachodzie. $B$B', '', '', '', '', '', '', 0),
(5441, 'koKR', 'Leniwe peony', 'Przeklęte peony! Harują przy wyrębie drzew w dolinie, ale wciąż ucinają sobie drzemki! Potrzebuję kogoś, kto pomoże mi trzymać je w ryzach.$B$BWyglądasz na kogoś w sam raz do tej roboty. Masz, weź tę pałkę i przyłóż nią każdemu leniwemu peonowi, którego przyłapiesz na spaniu w pracy. Porządne pacnięcie od razu zapędzi go z powrotem do roboty! Jak skończysz, oddaj mi pałkę.$B$BParszywe obiboki...', 'Użyj pałki brygadzisty na leniwych peonach, gdy śpią. Obudź 5 peonów, a potem oddaj pałkę brygadzisty brygadziście Thazz\'rilowi w Dolinie Prób.', '', 'Wróć do brygadzisty Thazz\'rila w Durotarze.', 'Obudzone peony', '', '', '', 0),
(5648, 'koKR', 'Szaty duchowości', 'Czas na twoją pierwszą próbę, $N. Na południe od Brzytwogóry, tuż za osadą, jedna z naszych siepaczek została ranna w walce z dawnymi żołnierzami Proudmoore\'a. Nie jest z nią dobrze i bardzo by jej pomogło, gdyby ktoś z naszych się nią zajął. Znajdź ją – nazywa się Kor\'ja – ulecz jej rany i udziel jej błogosławieństwa naszych przodków.$B$BJeśli to zrobisz, uznam, że to wystarczający dowód, że możesz iść dalej naszą drogą.', 'Odnajdź siepaczkę Kor\'ję i ulecz jej rany czarem Pomniejsze leczenie (ranga 2). Następnie rzuć na nią Słowo mocy: Wytrwałość i wróć do Tai\'jin w Brzytwogórze.', '', 'Wróć do Tai\'jin w Brzytwogórze w Durotarze.', 'Ulecz i wzmocnij siepaczkę Kor\'ję', '', '', '', 0),
(5649, 'koKR', 'W łasce duchów', 'O tak. Nasz lud przyłączył się do Hordy, bo to nam dobrze służy. Orkowie są lojalni i wiele nas uczą o takich sprawach jak honor. Ale stare obyczaje trudno porzucić. Orkowie mogą nie pochwalać wszystkich naszych tradycji, ale to nie znaczy, że nie możemy niektórych z nich dalej pielęgnować po cichu.$B$BWiesz o tym i dlatego wysyłam cię do Tai\'jin w Brzytwogórze. Ona nauczy cię więcej o naszej historii. Nauczy cię obyczajów naszego plemienia. Idź do niej, gdy będziesz $ggotów:gotowa;.', 'Porozmawiaj z Tai\'jin w Durotarze.', '', '', '', '', '', '', 0),
(5843, 'koKR', 'Witaj!', 'Witaj w świecie World of Warcraft!$B$BW podziękowaniu za zakup Edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Maggdze w Brzytwogórze. Otrzymasz w zamian prezent: małego towarzysza, który będzie ci towarzyszył w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w świecie World of Warcraft!', 'Zanieś bon podarunkowy z Brzytwogóry Maggdze w Brzytwogórze.', '', '', '', '', '', '', 0),
(6065, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Yawa Ostrogrzywego w Wiosce Krwawego Kopyta. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Yawem Ostrogrzywym w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', '', '', 0),
(6066, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Yawa Ostrogrzywego w Wiosce Krwawego Kopyta. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Yawem Ostrogrzywym w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', '', '', 0),
(6067, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Yawa Ostrogrzywego w Wiosce Krwawego Kopyta. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Yawem Ostrogrzywym w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', '', '', 0),
(6068, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Thotara w Brzytwogórze. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Thotarem w Brzytwogórze w Durotarze.', '', '', '', '', '', '', 0),
(6069, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Thotara w Brzytwogórze. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Thotarem w Brzytwogórze w Durotarze.', '', '', '', '', '', '', 0),
(6070, 'koKR', 'Ścieżka łowcy', 'Witaj, $gmłody łowco:młoda łowczyni;. Wyglądasz mi na kogoś dość wprawnego, by poradzić sobie z bestią i wyszkolić ją na swojego towarzysza.$B$BMusisz odwiedzić Thotara w Brzytwogórze. On wskaże ci ścieżkę do zdobycia własnego zwierzęcia.', 'Porozmawiaj z Thotarem w Brzytwogórze w Durotarze.', '', '', '', '', '', '', 0),
(6394, 'koKR', 'Kilof Thazz\'rila', '$N, można na tobie polegać. Mogę ci powierzyć jeszcze jedno zadanie?$B$BJakiś czas temu badałem jaskinię na północy w poszukiwaniu minerałów i zostawiłem tam mój ulubiony kilof. Kiedy później po niego wróciłem, jaskinia roiła się od groźnych bestii! Wejdziesz do tej jaskini, do Sabatu Płonącego Ostrza, i przyniesiesz mój kilof?$B$BZostawiłem go w komnacie z wodospadami. Na kilofie jest zaklęcie, dzięki któremu widać go w ciemności, więc nie musisz się martwić, że go nie znajdziesz... tylko tym, co go pilnuje!', 'Przynieś kilof Thazz\'rila brygadziście Thazz\'rilowi.', '', 'Wróć do brygadzisty Thazz\'rila w Durotarze.', '', '', '', '', 0),
(6623, 'koKR', 'Oddział Urazowy Hordy', 'Doktor $N, jak mniemam. Miło cię znowu widzieć.$B$BMam dla ciebie wspaniałe wieści! Doktor Gregory Victor, naczelny lekarz Oddziału Urazowego Hordy, osobiście poprosił, byś $gdołączył:dołączyła; do niego w Młotogrodzie. To może być okazja życia! Oddałbym wszystko za szansę nauki u wielkiego doktora Gregory\'ego Victora! Nie zmarnuj tej okazji!', 'Udaj się do Młotogrodu na Wyżynach Aratorskich i porozmawiaj z doktorem Gregorym Victorem o wstąpieniu w szeregi Oddziału Urazowego Hordy.$B', '', '', '', '', '', '', 0),
(7664, 'koKR', 'Zamiennik kremowego raptora', '', '', '', 'Wróć do Zjolnira w Durotarze.', '', '', '', '', 0),
(7665, 'koKR', 'Zamiennik czerwonego raptora', '', '', '', 'Wróć do Zjolnira w Durotarze.', '', '', '', '', 0),
(8150, 'koKR', 'Hołd dla bohatera', 'Podczas Dożynek w Azeroth dziękujemy bohaterom za ofiary – czasem te najwyższe – które ponieśli dla nas. Horda czci wielu bohaterów, ale nikt nie uosabia siły i poświęcenia lepiej niż Grom Piekłorycz.$B$BPomóż nam uczcić Groma i zanieś ten trybut pod jego pomnik w Kanionie Upadku Demona w Jesionowej Kniei. Złóż go u podstawy, a potem wróć do mnie. Będę tu tylko do końca święta, więc nie zwlekaj z oddaniem hołdu Gromowi.', 'Udaj się do Pomnika Groma w Kanionie Upadku Demona w Jesionowej Kniei i użyj trybutu Groma u podstawy pomnika. Wróć do Javnira Nashaka przed Orgrimmarem, zanim skończą się Dożynki.', 'Złóż trybut przy Pomniku Groma', 'Wróć do Javnira Nashaka w Durotarze.', '', '', '', '', 0),
(8358, 'koKR', 'Nadjeżdża żelek!', 'Zbieracz słodyczy! No proszę!$B$BNo cóż, choć robisz coś szlachetnego i zbierasz cukierki dla chorego dziecka, nie mogę ci tak łatwo odpuścić. Mam dla chorego dziecka pysznego żelka Mrocznej Włóczni... jeśli zrobisz dla mnie odgłos pociągu! Haha, tak, to będzie ta sztuczka! Cena tego żelka to jeden odgłos pociągu!$B$BCiuch-ciuch, $N!$B', 'Wykonaj emotkę pociągu (/train) przed Kali Remik, a w zamian otrzymasz żelka Mrocznej Włóczni!$B', '', 'Wróć do Kali Remik na Wybrzeżu Mrocznych Włóczni w Durotarze.', 'Zrób „pociąg” dla Kali Remik', '', '', '', 0),
(8670, 'koKR', 'Nestor Runiczny Totem', '', '', '', '', '', '', '', '', 0),
(9617, 'koKR', 'Odszukaj Obieżyświatów', 'Porucznik Świtobieżna z Ustronia Obieżyświatów prosi o spotkanie ze wszystkimi zdolnymi łowcami. Wiele zyskasz, jeśli ją odszukasz, $N. Dla tych, którzy podążają naszą drogą, jest skarbnicą mądrości.$b$bUstronie Obieżyświatów leży na południe od Srebrnej Luny.', 'Porozmawiaj z porucznik Świtobieżną w Ustroniu Obieżyświatów.', '', '', '', '', '', '', 0),
(10529, 'koKR', 'Ścieżka łowcy', 'Porucznik Świtobieżna z Ustronia Obieżyświatów prosi o spotkanie ze wszystkimi zdolnymi łowcami. Wiele zyskasz, jeśli ją odszukasz, $N. Dla tych, którzy podążają naszą drogą, jest skarbnicą mądrości.$b$bUstronie Obieżyświatów leży na południe od Srebrnej Luny.', 'Porozmawiaj z porucznik Świtobieżną w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(10530, 'koKR', 'Ścieżka łowcy', 'Porucznik Świtobieżna z Ustronia Obieżyświatów prosi o spotkanie ze wszystkimi zdolnymi łowcami. Wiele zyskasz, jeśli ją odszukasz, $N. Dla tych, którzy podążają naszą drogą, jest skarbnicą mądrości.$b$bUstronie Obieżyświatów leży na południe od Srebrnej Luny.', 'Porozmawiaj z porucznik Świtobieżną w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(10790, 'koKR', 'Powrót do Gan\'rula Krwawego Oka', 'Daleko ci do domu, $N. Może czas wrócić i uczyć się u twojego mistrza, Gan\'rula Krwawego Oka. Jego wiedzę znają wszyscy parający się naszym rzemiosłem, nawet my tutaj.$b$bGan\'rul przebywa w Szczelinie Cienia w Orgrimmarze.', 'Porozmawiaj z Gan\'rulem Krwawe Oko w Orgrimmarze.', '', '', '', '', '', '', 0),
(11219, 'koKR', 'Zatrzymaj pożary!', 'Dzieci Hordy cię potrzebują, $n. Bezgłowy Jeździec, niegdyś ludzki paladyn, a dziś obłąkany potwór, podpalił naszą wioskę! Musisz ugasić te pożary!$B$BChwyć wiadro i chluśnij wodą w ogień albo rzuć je sojusznikowi, który stoi bliżej płomieni. Ugaś wszystkie pożary i pokrzyżuj plany Bezgłowego Jeźdźca!', 'Zamaskowana opiekunka sierocińca chce, żebyś $gpomógł:pomogła; ugasić wszystkie pożary w wiosce. Gdy zgasną, porozmawiaj ponownie z zamaskowaną opiekunką sierocińca w osadzie.', 'Ugaś pożary', 'Wróć do zamaskowanej opiekunki sierocińca.', '', '', '', '', 0),
(11220, 'koKR', 'Bezgłowy Jeździec', 'Dopóki głowa Bezgłowego Jeźdźca nie zostanie zniszczona, jego szał się nie skończy.$B$BJeździec spoczywa w Opuszczonym Krużganku Szkarłatnego Klasztoru na Polanach Tirisfal. Idź do jego dyniowej kapliczki i wypowiedz te słowa:$B$B  Powstań, Jeźdźcu,$B  twój czas nadchodzi.$B  Śmierć już znasz –$B  dziś zguba cię ugodzi!$B$BTo zbudzi potwora. Zniszcz głowę Jeźdźca, a nie będzie nas już dręczył.', 'Odszukaj dyniową kapliczkę Bezgłowego Jeźdźca.', '', '', '', '', '', '', 0),
(11357, 'koKR', 'Zamaskowana opiekunka sierocińca', 'Z okazji Zaduszników orcze sieroty zabrano na wycieczkę po wielu wioskach Hordy. Opiekunki sierocińca uznały, że dobrze im zrobi widok prawdziwych bohaterów podczas wypraw.$B$BMoże je odwiedzisz? Opowieści o twoim męstwie na pewno dodałyby im ducha! Udaj się do Brzytwogóry w Durotarze, do Brill na Polanach Tirisfal albo na Plac Sokolego Skrzydła w Gaju Wszechpieśni. Porozmawiaj z zamaskowaną opiekunką sierocińca, a przedstawi cię dzieciom.', 'Porozmawiaj z zamaskowaną opiekunką sierocińca w Brzytwogórze, Brill albo na Placu Sokolego Skrzydła.', '', '', '', '', '', '', 0),
(11361, 'koKR', 'Szkolenie pożarnicze', 'Siepacze przygotowali pod wioską plac do ćwiczeń w gaszeniu pożarów. Ostatnio budynki w Brzytwogórze często stają w ogniu – przydałaby się twoja pomoc, więc przejdź szkolenie strażackie!$B$BWyjdź z Brzytwogóry na zachód, a potem skręć w prawo, gdy miniesz mur wioski. Znajdź plac ćwiczeń, chwytaj wiadra i wylewaj je na ćwiczebne ognie.', 'Wylej wiadra wody na 5 ogni, a następnie porozmawiaj z zamaskowaną opiekunką sierocińca w Brzytwogórze.', '', 'Wróć do zamaskowanej opiekunki sierocińca w Brzytwogórze w Durotarze.', 'Ugaszone ognie', '', '', '', 0),
(11403, 'koKR', 'Nareszcie wolny!', 'Wściekłość była moim więzieniem, $N, a ty mnie $guwolniłeś:uwolniłaś;. Choć sądziłem, że postępuję słusznie, moja dusza opłakuje teraz grozę i śmierć, które sprowadziłem na dobrych ludzi z Azeroth.$B$BDziękuję, że $gprzywiodłeś:przywiodłaś; mnie z powrotem do Światłości. Obym już nigdy nie zbłądził.$B$BZanieś ten podarty modlitewnik opiekunce sierocińca, aby dzieci wiedziały, że nie będę ich już nawiedzał.', 'Zanieś księgę Thomasa Thomsona zamaskowanej opiekunce sierocińca w Durotarze, Brill albo na Placu Sokolego Skrzydła.', '', 'Wróć do zamaskowanej opiekunki sierocińca.', '', '', '', '', 0),
(11407, 'koKR', 'Zachwalaj Gorzelnię Drohna!', 'To jak, chcesz pomóc wnieść siłę i honor do Festiwalu Piwa? Trzeba pokrzyczeć przy flagach przed domem aukcyjnym w Dolinie Siły, w Dolinie Honoru, w Dolinie Mądrości i w Dolinie Duchów.$b$bPożyczymy ci barana wyścigowego na 4 minuty i damy ci też te wodze wyścigowe.$b$bTylko uważaj, skąpe gobliny nie ustawiły po drodze skrzynek z jabłkami.', 'Rozgłoś wieść o Festiwalu Piwa przy flagach przed domem aukcyjnym w Dolinie Siły, w Dolinie Honoru, w Dolinie Mądrości i w Dolinie Duchów.', '', 'Wróć do Corta Goresteina w Durotarze.', 'Zachwalaj przed domem aukcyjnym', 'Zachwalaj w Dolinie Honoru', 'Zachwalaj w Dolinie Mądrości', 'Zachwalaj w Dolinie Duchów', 0),
(11408, 'koKR', 'Zachwalaj Browar Wudu T\'chalego!', 'Trzeba rozgłosić wieść o trollach na Festiwalu Piwa. Musisz pokrzyczeć przy flagach przed domem aukcyjnym w Dolinie Siły, w Dolinie Honoru, w Dolinie Mądrości i w Dolinie Duchów.$b$bAle ułatwię ci sprawę: pożyczę ci barana wyścigowego na 4 minuty. Dam ci też te wodze wyścigowe.$b$bTylko uważaj, gobliny nie ustawiły po drodze skrzynek z jabłkami. Takie z nich sknery.', 'Rozgłoś wieść o Festiwalu Piwa przy flagach przed domem aukcyjnym w Dolinie Siły, w Dolinie Honoru, w Dolinie Mądrości i w Dolinie Duchów.', '', 'Wróć do Ja\'rona w Durotarze.', 'Zachwalaj przed domem aukcyjnym', 'Zachwalaj w Dolinie Honoru', 'Zachwalaj w Dolinie Mądrości', 'Zachwalaj w Dolinie Duchów', 0),
(11413, 'koKR', 'Czy ktoś powiedział „pamiątka”?', 'Nie dość, że zaopatrujemy wszystkich w piwo, to jeszcze rozdajemy kufle! Piękne, pamiątkowe kufle, a wszystkie zdobyte jak najbardziej legalnie! Masz tu bon na jeden.$b$bPogadaj z Blixem na tyłach obozu Festiwalu Piwa. Dziwny z niego gość, a jeszcze dziwniejszy, odkąd ciągle nosi te gogle. Zrealizuje ci bon i załatwi każdą inną transakcję na Festiwalu Piwa.', 'Zrealizuj bon na kufel Festiwalu Piwa u Blixa Fixwidgeta na tyłach obozu Festiwalu Piwa.', '', 'Wróć do Blixa Fixwidgeta w Durotarze.', '', '', '', '', 0),
(11449, 'koKR', 'Szkolenie pożarnicze', 'Tropiciele śmierci przygotowali pod miastem plac do ćwiczeń w gaszeniu pożarów. Nie możemy pozwolić na dalsze zniszczenia budynków w Brill – spełnij swój obowiązek i przejdź szkolenie strażackie.$B$BIdź drogą na zachód, mijając cmentarz. Tam znajdziesz plac ćwiczeń.', 'Wylej wiadra wody na 5 ogni, a następnie porozmawiaj z zamaskowaną opiekunką sierocińca w Brill.', '', 'Wróć do zamaskowanej opiekunki sierocińca w Brill na Polanach Tirisfal.', 'Ugaszone ognie', '', '', '', 0),
(11450, 'koKR', 'Szkolenie pożarnicze', 'Strażnicy przygotowali pod miastem plac do ćwiczeń w gaszeniu pożarów. Nie możemy pozwolić, by Jeździec zniszczył to, co z takim trudem odbudowaliśmy – spełnij swój obowiązek i przejdź szkolenie strażackie.$B$BIdź na południe przez bramę, do rozstaju dróg. Tam znajdziesz plac ćwiczeń.', 'Wylej wiadra wody na 5 ogni, a następnie porozmawiaj z zamaskowaną opiekunką sierocińca na Placu Sokolego Skrzydła.', '', 'Wróć do zamaskowanej opiekunki sierocińca na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', 'Ugaszone ognie', '', '', '', 0),
(11915, 'koKR', 'Igranie z ogniem', 'Chcesz się nauczyć kilku gorących nowych sztuczek?$b$bNie wiem, czy kiedykolwiek dorównasz mojemu niemałemu kunsztowi, ale jeśli będziesz uważać na lekcjach, pewnie podłapiesz to i owo. Porozmawiaj z mistrzem połykaczy płomieni w dowolnej stolicy Hordy. Któryś z nich powinien ci pomóc.', 'Porozmawiaj z mistrzem połykaczy płomieni w dowolnej stolicy Hordy.', '', '', '', '', '', '', 0),
(11966, 'koKR', 'Kadzidło dla festiwalowych żarzątek', 'Czy wiesz, że nasze festiwalowe ognie płoną w każdej krainie, w której jest osada Hordy? Opiekunowie płomienia doglądają ich w obozach pod każdym miastem i dbają o to, by ogniska płonęły jasno, a zabawa trwała.$b$bKażdemu opiekunowi płomienia towarzyszy festiwalowe żarzątko – wysłannik do żywiołowych duchów ognia.$B$BChcesz uczcić żarzątko, $N? Weź to letnie kadzidło i zanieś je dowolnemu festiwalowemu żarzątku. Udobruchaj małego ducha ognia, a może cię wynagrodzi.', 'Festiwalowy bajarz chce, żebyś $gzaniósł:zaniosła; letnie kadzidło festiwalowemu żarzątku przed dowolną osadą Hordy.', '', 'Wróć do festiwalowego żarzątka.', '', '', '', '', 0),
(12139, 'koKR', '„Niech przyjdą płomienie!”', 'Bezgłowy Jeździec lada chwila zaatakuje wioskę! Wszędzie będzie płonął ogień!$B$B$n, czy stawisz czoło płomieniom Bezgłowego Jeźdźca? Kiedy nadjedzie, musisz dołączyć do straży pożarnej. Chwyć wiadro i chluśnij wodą w ogień albo podaj je komuś, kto stoi bliżej płomieni. Jeśli ugasisz wszystkie pożary, może jeszcze zdołamy się uratować!', 'Zamaskowana opiekunka sierocińca chce, żebyś $gpomógł:pomogła; ugasić wszystkie pożary w wiosce. Gdy zgasną, porozmawiaj ponownie z zamaskowaną opiekunką sierocińca w osadzie.', 'Ugaś pożary', 'Wróć do zamaskowanej opiekunki sierocińca.', '', '', '', '', 0),
(12155, 'koKR', 'Rozbij dynię', 'Ta wielka latarnia z dyni stoi pośrodku wioski. Wodzi wzrokiem za tymi, którzy na nią patrzą, zdradzając czające się w niej mroczne zło.$B$BPo rozbiciu dyni ukazuje się stary, osmalony święty symbol.', 'Oddaj osmalony święty symbol zamaskowanej opiekunce sierocińca.', '', 'Wróć do zamaskowanej opiekunki sierocińca.', '', '', '', '', 0),
(12194, 'koKR', 'A nie znalazłaby się przypadkiem w tym roku jakaś pamiątka?', 'Nie dość, że zaopatrujemy wszystkich w piwo, to jeszcze rozdajemy kufle! Piękne, pamiątkowe kufle, a wszystkie zdobyte jak najbardziej legalnie! Masz tu bon na jeden.$b$bPogadaj z Blixem na tyłach obozu Festiwalu Piwa. Dziwny z niego gość, a jeszcze dziwniejszy, odkąd ciągle nosi te gogle. Zrealizuje ci bon i załatwi każdą inną transakcję na Festiwalu Piwa.', 'Zrealizuj bon na kufel Festiwalu Piwa u Blixa Fixwidgeta na tyłach obozu Festiwalu Piwa.', '', 'Wróć do Blixa Fixwidgeta w Durotarze.', '', '', '', '', 0),
(13479, 'koKR', 'Wielkie polowanie na jajka', 'Miłogrody, święto życia i wiosny! Mam nadzieję, że polowanie na jajka sprawia ci frajdę, bo przydałaby mi się pomoc kogoś tak zaradnego jak ty.$b$bNie mam pewności, jakiej magii użyto do stworzenia tych jajek, a druidzi nie kwapią się, by mi to wyjaśnić. Może przy okazji zbierania jajek zdobędziesz dla mnie trochę fragmentów skorupek? Zawartość jajek możesz zatrzymać – mnie potrzeba tylko odpowiednio dużej próbki samych jajek.', 'Wiosenny zbieracz chce, żebyś $gzdobył:zdobyła; 20 fragmentów skorupek.', '', 'Wróć do wiosennego zbieracza.', '', '', '', '', 0),
(13483, 'koKR', 'Wiosenni zbieracze', 'Jeśli szukasz jakiegoś zajęcia, to podobno w osadach pod stolicami – w Brzytwogórze, Brill, Wiosce Krwawego Kopyta i na Placu Sokolego Skrzydła – są magowie, którzy werbują łowców jajek do pomocy w jakichś badaniach. Nie znam szczegółów, ale na pewno ci je wyjaśnią.', 'Porozmawiaj z wiosennym zbieraczem w Brzytwogórze, Brill, Wiosce Krwawego Kopyta albo na Placu Sokolego Skrzydła.', '', '', '', '', '', '', 0),
(13503, 'koKR', 'Koszyczek, koszyczek, miłogrodzki koszyczek', 'Proszę... weź ten koszyk na jajka i ruszaj na poszukiwanie jaskrawo zabarwionych jajek. Wróć do mnie z koszykiem, gdy znajdziesz dziesięć czekoladek z Miłogrodów.', 'Miłogrodzki kupiec chce, żebyś $gzebrał:zebrała; 10 czekoladek z Miłogrodów i $gprzyniósł:przyniosła; je razem z koszykiem na jajka.', '', 'Wróć do miłogrodzkiego kupca.', '', '', '', '', 0),
(14040, 'koKR', 'Placek dyniowy', 'Ten twój farsz z chleba z przyprawami zrobił furorę, ale żadna uczta na Dary Pielgrzymów nie obejdzie się bez kawałka placka dyniowego. To kolejne tradycyjne tutejsze danie, bo robi się je z dojrzałych dyń z Tirisfal, które rosną tylko w tej okolicy.$B$BJeśli nie umiesz jeszcze piec placka dyniowego, przepis znajdziesz w swojej obfitej książce kucharskiej.$B$BMożesz upiec kilka kawałków i zanieść je Francisowi Eatonowi pod Orgrimmar? Pewnie już mu się kończą.', 'Upiecz 5 kawałków placka dyniowego i zanieś je Francisowi Eatonowi na miejsce uczty tuż pod Orgrimmarem.', '', 'Wróć do Francisa Eatona na Farmie Ostroknur w Durotarze.', 'Upiecz placek dyniowy', '', '', '', 0),
(14041, 'koKR', 'Żurawinowe chutney', '$GPróbowałeś:Próbowałaś; już żurawinowego chutney? Robi się je ze świeżej cierpkiej żurawiny znad Południowej Furii. Jeśli chcesz spróbować swoich sił, kup trochę u sprzedawcy Darów Pielgrzymów.$B$BPrzepis powinien być w twojej obfitej książce kucharskiej.$B$BGdybyś $gmiał:miała; wolną chwilę, możesz przyrządzić trochę chutney i zanieść je Dokinowi Dalekiej Równinie u stóp windy po zachodniej stronie Gromowych Urwisk?', 'Przyrządź 5 porcji żurawinowego chutney i zanieś je Dokinowi Dalekiej Równinie u stóp windy po zachodniej stronie Gromowych Urwisk.', '', 'Wróć do Dokina Dalekiej Równiny w Gromowych Urwiskach.', 'Przyrządź żurawinowe chutney', '', '', '', 0),
(14043, 'koKR', 'Kandyzowane bataty', 'Skoro już tu jesteś, może zaopatrz się w bataty z Mulgoru. Robi się z nich pyszne kandyzowane bataty, moją ulubioną część posiłku na Dary Pielgrzymów.$B$BJeśli mi nie wierzysz, znajdź przepis w swojej obfitej książce kucharskiej i spróbuj. Jeśli wracasz do Orgrimmaru, zanieś je Francisowi Eatonowi na miejsce uczty tuż pod miastem. Staram się go zaopatrywać, ale tam wszystko znika w mgnieniu oka.', 'Przyrządź 5 porcji kandyzowanych batatów i zanieś je Francisowi Eatonowi tuż pod Orgrimmar.', '', 'Wróć do Francisa Eatona na Farmie Ostroknur w Durotarze.', 'Przyrządź kandyzowany batat', '', '', '', 0),
(14044, 'koKR', 'Braki w Podmieście', 'Dzięki za kandyzowane bataty. Tyle jest gotowania, że ledwo nadążam. A tu jeszcze Miles przysyła mi wiadomość, że lada chwila skończy mu się farsz i żurawinowe chutney. Może $gzechciałbyś:zechciałabyś; pomóc i przyrządzić jeszcze trochę jednego i drugiego? Sprzedawca powinien mieć wszystkie potrzebne składniki.$B$BMilesa Standisha znajdziesz przy biesiadnych stołach na dziedzińcu w ruinach nad Podmiastem.', 'Zanieś 5 porcji farszu z chleba z przyprawami i 5 porcji żurawinowego chutney Milesowi Standishowi przy wejściu do Podmiasta.', '', 'Wróć do Milesa Standisha w Ruinach Lordaeronu na Polanach Tirisfal.', '', '', '', '', 0),
(14047, 'koKR', 'Wolno pieczony indyk', 'Każda uczta na Dary Pielgrzymów potrzebuje ozdoby stołu, a dla nas jest nią wolno pieczony dziki indyk. Nie przychodzi mi do głowy nic, co lepiej spinałoby cały posiłek.$B$BDobry przepis znajdziesz w swojej obfitej książce kucharskiej. Może upolujesz kilka dzikich indyków i je przyrządzisz? Indyki wałęsają się po całych Polanach Tirisfal, więc ze znalezieniem ich nie powinno być kłopotu.$B$BA gdy już je upieczesz, zaniesiesz je Francisowi Eatonowi pod Orgrimmar?', 'Upiecz 5 wolno pieczonych indyków i zanieś je Francisowi Eatonowi pod bramy Orgrimmaru.', '', 'Wróć do Francisa Eatona na Farmie Ostroknur w Durotarze.', 'Upiecz wolno pieczonego indyka', '', '', '', 0),
(14061, 'koKR', 'Indyka nigdy dość', 'Gotuję bez przerwy od czasu sprzed początku święta i wciąż nie nadążam z zamówieniami. Nie dałoby się cię namówić do pomocy przy jednej z potraw?$B$BO indyka tutaj trudno, więc bardzo byś mi $gpomógł:pomogła;, dostarczając trochę wolno pieczonych indyków. Jeśli zamierzasz $gsam:sama; je przyrządzić, na świeże dzikie indyki możesz polować na całych Polanach Tirisfal. Wszystko inne, czego ci trzeba, kupisz u dowolnego sprzedawcy Darów Pielgrzymów.', 'Przynieś 20 wolno pieczonych indyków Ondani Wielki Młyn pod Orgrimmar.', '', 'Wróć do Ondani Wielki Młyn na Farmie Ostroknur w Durotarze.', '', '', '', '', 0),
(14062, 'koKR', 'Nie zapomnij o farszu!', 'Pilnowanie, żeby na tych stołach niczego nie zabrakło, potrafi przytłoczyć! Muszę robić żurawinowe chutney, mieć oko na bataty i uważać, żeby placki się nie przypaliły.$B$BChyba wszystko mam pod kontrolą. Nie, zaraz, o czymś zapominam. Farsz! O nie. Nie zdążę nastawić kolejnej porcji farszu, zanim cała reszta będzie gotowa. Zechcesz mi pomóc? Kupienie albo przyrządzenie farszu nie powinno zająć dużo czasu, a składniki dostaniesz na miejscu.', 'Przynieś 20 porcji farszu z chleba z przyprawami Ondani Wielki Młyn pod Orgrimmar.', '', 'Wróć do Ondani Wielki Młyn na Farmie Ostroknur w Durotarze.', '', '', '', '', 0),
(14065, 'koKR', 'Wspólna obfita uczta', 'Kto nie najadł się do syta przy obfitym stole, ten nie świętował Darów Pielgrzymów jak należy.$B$BProszę, siadaj, ucztuj i spróbuj wszystkiego! Możesz przesiadać się z krzesła na krzesło albo poprosić innych przy stole, żeby podali ci coś ze swoich potraw.$B$BGdy zjesz wystarczająco dużo każdego dania, napełni cię Duch dzielenia się.', 'Zjedz po pięć porcji każdej potrawy przy obfitym stole, aż zyskasz Ducha dzielenia się.', '', 'Wróć do gospodyni obfitej uczty.', 'Duch dzielenia się', '', '', '', 0),
(14088, 'koKR', 'Naucz się jeździć w Durotarze', 'Tę ulotkę reklamującą naukę jazdy i sprzedaż wierzchowców przysłał Xar\'Ti.$B$BXar\'Tiego znajdziesz w Wiosce Sen\'jin w południowym Durotarze.', 'Zanieś ulotkę Xar\'Tiemu do Wioski Sen\'jin w południowym Durotarze.', '', 'Wróć do Xar\'Tiego na Wybrzeżu Mrocznych Włóczni w Durotarze.', '', '', '', '', 0),
(14175, 'koKR', 'Wdzięczni umarli', 'Dobrze znów odwiedzić przyjaciół i rodzinę, choć chyba trochę przesadziłam... Zjadłam już wszystko, co dla mnie przygotowali!$B$BCzy mogę cię prosić o jeszcze trochę tego pysznego chleba umarłych? Będę bardzo wdzięczna...$B$BPrzepis sprzedaje chyba tamten Chapman.', 'Zdobądź chleb umarłych i daj go radosnemu duchowi orka na cmentarzu w Orgrimmarze.$B$BUżyj pomarańczowej aksamitki, aby zobaczyć niewidzialnego na co dzień ducha.', '', 'Wróć do radosnego ducha orka w Durotarze.', '', '', '', '', 0),
(14177, 'koKR', 'Wdzięczni umarli', 'Dobrze znów odwiedzić przyjaciół i rodzinę, choć chyba trochę przesadziłam... Zjadłam już wszystko, co dla mnie przygotowali!$B$BCzy mogę cię prosić o jeszcze trochę tego pysznego chleba umarłych? Będę bardzo wdzięczna...$B$BPrzepis sprzedaje chyba tamten Chapman.', 'Zdobądź chleb umarłych i daj go radosnemu duchowi trolla na cmentarzu w Orgrimmarze.$B$BUżyj pomarańczowej aksamitki, aby zobaczyć niewidzialnego na co dzień ducha.', '', 'Wróć do radosnego ducha trolla w Durotarze.', '', '', '', '', 0),
(25343, 'koKR', 'Plan Mistrza', 'Dobrze się tu odnajdujesz, $N, ale jesteśmy czymś więcej niż codziennymi obowiązkami i szerzeniem przesłania. Na pewno trochę o tym $gsłyszałeś:słyszałaś;, gdy do nas $gdołączyłeś:dołączyłaś;.$B$BJak wiesz, ten świat się kończy, a nieprzygotowani zginą w męczarniach.$B$BOtrzymaliśmy dar – szansę, by stać się kimś większym i potężniejszym. Nadzorca Golbaz przygotowuje rytuał przy ołtarzu na wschodnim krańcu farmy. Zaczekaj tam na niego i dowiedz się więcej o swoich nowych braciach i siostrach.', 'Dowiedz się więcej o planach kultu przy ołtarzu we wschodniej części Farmy Ostroknur.', '', 'Wróć do nadzorczyni Jintak na Farmie Ostroknur.', 'Objawienie Cho\'galla', '', '', '', 0),
(25380, 'koKR', 'Szerzenie słowa', 'Witaj na farmie, $N. Każdy tutaj pracuje na swoje utrzymanie. Niektórzy doglądają zwierząt. Inni odpowiadają za nasze prace budowlane. Jeszcze inni szerzą nasze przesłanie wśród ludzi i myślę, że od tego dobrze będzie ci zacząć.$B$BWeź tę tablicę. Jest na niej krótkie przesłanie o naszej wierze. Nosząc ją, odwiedź wschodnią i zachodnią wieżę sterowców przed bramami Orgrimmaru oraz rynek w Brzytwogórze na południu.', 'Nosząc wiadomość o końcu świata, odwiedź wschodnią wieżę sterowców, zachodnią wieżę sterowców i rynek w Brzytwogórze.', '', 'Wróć do nadzorczyni Jintak na Farmie Ostroknur.', 'Szerz przesłanie przy wschodniej wieży sterowców', 'Szerz przesłanie przy zachodniej wieży sterowców', 'Szerz przesłanie w Brzytwogórze', '', 0),
(25444, 'koKR', 'Idealni szpiedzy', 'No więc głupotą byłoby iść tam na ślepo, dlatego tworzę małych szpiegów, którzy zbiorą informacje dla Vol\'jina. On musi wiedzieć, co się dzieje na wyspach.$B$BPrzydałaby mi się pomoc, jeśli masz ochotę. Powiem ci, jak to się robi. Najpierw trzeba złapać żaby. Lubią siedzieć w cieniu palm wokół Sen\'jin.$B$BGdy już złapiesz żaby, przynieś je tutaj, do mojego totemu wartowniczego, i dostrój je do mojego wzroku.', 'Złap 5 żab z Sen\'jin i dostrój je do wzroku Vaniry przy jej totemie wartowniczym.', '', 'Wróć do Vaniry na Wybrzeżu Mrocznych Włóczni.', '', 'Dostrojone żaby z Sen\'jin', '', '', 0),
(25445, 'koKR', 'Upadek Zalazanego', 'Nadszedł czas bitwy! Niedługo ruszamy na wyspy, więc lepiej bądź $ggotów:gotowa;.$B$BZalazane nie ma już wiele czasu.', 'Pomóż Vol\'jinowi odbić Wyspy Echa i zabij Zalazanego.', '', 'Wróć do Vol\'jina przed Wioską Sen\'jin.', 'Zalazane zabity', '', '', '', 0),
(25446, 'koKR', 'Żaby w drogę!', 'Żaby są gotowe, więc potrzebuję twojej pomocy, żeby wysłać je na wyspy.$B$BPo wschodniej stronie Wioski Sen\'jin znajdziesz tresera Marnleka. Zajmuje się wszystkimi nietoperzami zwiadowców Vol\'jina i może ci pożyczyć nietoperza, żeby dostać się na wyspy.$B$BWeź ze sobą ten wór żab. Prosiłam duchy o wskazówki. Zesłały dym, który pokaże ci, gdzie najbardziej potrzebuję oczu. Lecąc na nietoperzu, sięgnij do worka i rzucaj żaby w stronę białego dymu.', 'Lecąc na nietoperzu, użyj wora żab, żeby umieścić 12 dostrojonych żab przy znacznikach na Wyspach Echa.', '', 'Wróć do Vaniry w Wiosce Sen\'jin.', 'Rozmieszczone dostrojone żaby', '', '', '', 0),
(25461, 'koKR', 'Trollowy werbunek', 'Vol\'jin dał mi swoje bębny wojenne i powierzył szkolenie nowych rekrutów. Kłopot w tym, że brakuje nam rekrutów.$B$BGdybym pożyczył ci ten bęben, $gużyłbyś:użyłabyś; go, żeby w imieniu Vol\'jina wezwać do wojny w Brzytwogórze? Nawet jeśli porwiesz do walki tylko kilka trolli, to już coś zmieni. Kiedy przekonasz ich, żeby się zgłosili, przyprowadź ich do mnie na szkolenie. Idź do tresera Marnleka, na południe stąd. Pożyczy ci nietoperza na lot do Brzytwogóry.', 'Użyj bębnów wojennych Vol\'jina, żeby zwerbować 5 trolli mieszkających w Brzytwogórze.$B$BTreser Marnlek może ci dać nietoperza na lot do Brzytwogóry.', '', 'Wróć do czempiona Uru\'zina w Wiosce Sen\'jin.', 'Zwerbowani trolle ochotnicy', 'Trolle ochotnicy doprowadzeni do czempiona Uru\'zina', '', '', 0),
(25470, 'koKR', 'Pani tygrysów', 'Pamiętasz żaby, które $gzrobiłeś:zrobiłaś; moimi oczami i uszami? No więc znalazły coś ciekawego.$B$BNa wyspie na południowym wschodzie wypatrzyły tygrysicę, której boją się nawet inne koty. Nigdy nie widziałam czegoś takiego.$B$BPoluje z instynktem kota, ale ma umysł osoby. Może być potężnym duchem i silnym sojusznikiem.$B$BPrzywołam na ciebie ducha tygrysa. Użyj jego darów, żeby wytropić tę tygrysicę i rzucić jej wyzwanie. Zobacz, czy zdołasz pozyskać jej pomoc w naszej bitwie o wyspy.', 'Pod wpływem Ducha tygrysa wywabisz tygrysią matriarchę z kryjówki i pokonasz ją w walce dzięki nowym zdolnościom.', '', 'Wróć do Vol\'jina w Wiosce Sen\'jin.', 'Rzuć wyzwanie tygrysiej matriarsze', '', '', '', 0),
(25480, 'koKR', 'Taniec duchów', 'Nadszedł czas, by pomyśleć, kiedy wykonać nasz ruch. Czempion Uru\'zin mówi, że jego ludzie są gotowi. Ty i Vanira dobrze się spisaliście, zbierając informacje o wrogu i znajdując nam nowych sojuszników.$B$BTeraz odczytamy znaki. Dowiemy się, kiedy przypuścić atak.$B$BZnajdź znachora Hez\'toka przy kręgu tancerzy rytualnych. Zacznie rytuał, gdy tylko będziesz $ggotów:gotowa;.', 'Gdy zechcesz poznać znaki, porozmawiaj ze znachorem Hez\'tokiem przy kręgu tancerzy rytualnych przed Wioską Sen\'jin.', '', 'Wróć do Vol\'jina w pobliżu Wioski Sen\'jin.', 'Taniec duchów', '', '', '', 0),
(25495, 'koKR', 'Przygotowania do bitwy', 'Vol\'jin zbiera ekwipunek i szykuje wojowników. Prosi, by ci przekazać, że czeka na ciebie razem z Vanirą na wyspie na wschodzie.$B$BStamtąd on i wojownicy przypuszczą atak na Zalazanego. Niech przodkowie będą z tobą, $N. Bez ciebie ta kampania byłaby tylko cieniem tego, czym się stanie. Porozmawiaj z treserem Marnlekiem, tuż na południe stąd, a da ci nietoperza, żeby dolecieć na miejsce zbiórki.', 'Porozmawiaj z treserem Marnlekiem, żeby polecieć na miejsce zbiórki. Spotkaj się z Vol\'jinem na wyspie na wschód od obozu wojennego.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(784, 'koKR', 'Wieść o twojej odwadze szybko się niesie, $N. Opowieści o twoim zwycięstwie w Twierdzy Tiragarde rozbrzmią w całym Orgrimmarze.', 0),
(786, 'koKR', 'Horda z pewnością by zwyciężyła, gdyby centaury Kolkarów uderzyły. Ale zapobiegając takiemu atakowi, oszczędziliśmy naszym potężnym wojownikom niepotrzebnego rozlewu krwi.$B$BLecz tak pewne, jak to, że na pustyni Tanaris jest piasek, jest to, że zanim te ciężkie czasy przeminą, krew jeszcze się poleje.$B$BDobrze $gsłużyłeś:służyłaś; swojemu ludowi, $N.', 0),
(787, 'koKR', 'Kolejny rekrut Eitrigga, co?$B$BMarny nasz los, jeśli to najlepsze, na co stać Hordę. Nieważne. Zanim uznamy, że możesz opuścić Dolinę, staniesz się $gdumnym wojownikiem:dumną wojowniczką; Hordy.', 0),
(788, 'koKR', 'Hmm, nieźle, $N. Ale niech ci to nie uderzy do głowy... w swojej karierze będziesz walczyć z twardszymi przeciwnikami niż dziki.$b$bMimo to dobrze się $gspisałeś:spisałaś;, a w następnej próbie zmierzysz się ze znacznie groźniejszym przeciwnikiem, więc przyda ci się dodatkowa ochrona.', 0),
(789, 'koKR', 'Z walki ze skorpiadami musisz wynieść ważną lekcję. Nawet najmniejszy czy największy przeciwnik może cię posłać na zgubę. W zaciekłej walce zgubić cię może cokolwiek.$b$bNie mam cię już czego nauczyć, $N. Dobrze się $gspisałeś:spisałaś;, a ja będę z zainteresowaniem śledził twoje postępy.', 0),
(790, 'koKR', 'Mój cios nie wystarczył, by go zabić, ale widok zadanych przeze mnie ran daje mi odrobinę dumy. Ta odrobina będzie wszystkim, co mi zostanie, jeśli umrę, a w tym świetle krótka lista moich życiowych dokonań napełnia mnie gniewem.', 0),
(791, 'koKR', 'Doskonale, $N. Każdy porządny $c z pewnością znajdzie zastosowanie dla tej torby na polu bitwy.$b$bSalutuję twojemu zapałowi i gotowości, by zginąć w imię Hordy!', 0),
(792, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N.$b$bChoć plugawe chowańce były jedynie pupilami mroczniejszych mocy Płonącego Ostrza, twój sukces w walce z nimi zapowiada większe czyny.', 0),
(794, 'koKR', 'Udało ci się go odzyskać! Świetnie!$b$bTwoje wysiłki w Sabacie Płonącego Ostrza są kluczowe, by wykorzenić ten kult z Doliny Prób. Obawiam się jednak, że mają wobec naszej ziemi dalsze plany.$b$bJeszcze o nich usłyszymy.', 0),
(804, 'koKR', 'Z twojego opisu bestii wnoszę, że mówisz o Sarkocie! Nic dziwnego, że Hana\'zua mu uległ. Natychmiast wyślemy mu pomoc, nie zaprzątaj sobie już głowy jego losem.$b$bMuszę jednak przyznać, że jestem pod wielkim wrażeniem, słysząc, że $gzgładziłeś:zgładziłaś; Sarkotha. To wyczyn, z którego możesz być $gdumny:dumna;, $N. A to, że $gwalczyłeś:walczyłaś; o honor obcego, choć $gmiałeś:miałaś; inne zadania, jeszcze przydaje ci honoru.', 0),
(805, 'koKR', 'Hm... twój raport przychodzi w złym czasie. Płonącego Ostrza nie widać tu, w Sen\'jin, ale ich zło zapuściło korzenie u wybrzeża, na Wyspach Echa.$b$bOrkowie to przyjaciele Trolli Mrocznej Włóczni. Honorowi przyjaciele. Chcemy pomóc orkom, ale... my też potrzebujemy pomocy.$b', 0),
(806, 'koKR', 'Aha! $GDopadłeś:Dopadłaś; go!$b$bPrzynosisz chlubę swojemu klanowi, $N. A dzięki tobie Durotar jest wolny od jeszcze jednego sługi zła.', 0),
(808, 'koKR', 'Dziękuję, $N. $GOcaliłeś:Ocaliłaś; Minshinę. $GUwolniłeś:Uwolniłaś; ducha mojego brata z niewoli!', 0),
(809, 'koKR', 'Neeru chce zniszczyć Demoniczne Nasiono, tak? Dziwne...$b$bNiech będzie. Skoro chce się pozbyć nasiona, powiem ci, jak je usunąć.', 0),
(812, 'koKR', '$N, $guratowałeś:uratowałaś; mi życie. Dziękuję.$B$BProszę, weź to. Mam nadzieję, że przyda ci się w podróżach, a jak nie, to chociaż dostaniesz za to trochę grosza. Z tego, co mówisz, prędko mi się to nie przyda. Kor\'ghan przeciągnie mnie przez kolejne swoje rytuały, dopóki się nie wykażę. Znowu zabijanie dzików, znowu zbieranie ogonów skorpiad... <wzdycha>', 0),
(813, 'koKR', 'Oto antidotum, $N. Zanieś je Rhinagowi najszybciej, jak możesz, i uważaj na siebie.', 0),
(815, 'koKR', 'Może i jesteś $gsłaby:słaba;, ale przynajmniej nie masz dwóch lewych rąk, $N.$b$bMasz, weź to i zejdź mi z drogi. Muszę gotować.', 0),
(816, 'koKR', 'Och, mój syn... mój piękny syn.$b$bNie wiedząc, co się z nim stało, dręczyłam się od chwili, gdy odszedł. Teraz, gdy już wiem, może wreszcie zdołam zacząć go opłakiwać.$b$bDziękuję, $N. Proszę, weź to. Chciałam dać to Kronowi w prezencie, gdy wróci z udanego polowania. Teraz, gdy wiem, że nie żyje, nie mogę na to patrzeć.', 0),
(817, 'koKR', 'Jestem zadowolony, $N. Dzięki twojej pomocy nasz lud będzie chroniony i nie zmarznie, gdy zmienią się pory roku.$b$bDziękuję.', 0),
(818, 'koKR', 'Dobra robota, dziecko... naprawdę dobra robota.', 0),
(823, 'koKR', 'Tak? Masz coś do zameldowania? No to mów!', 0),
(825, 'koKR', 'Twoja misja odzyskania narzędzi zakończyła się sukcesem, $N. Dopilnuję, żeby trafiły do Orgrimmaru z następną karawaną.$b$bDobra robota.', 0),
(826, 'koKR', 'Skoro Zalazanego już nie ma, nasze plemię znów może spać spokojnie.$b$bDziękuję, $N. Plemię Mrocznej Włóczni wiele ci zawdzięcza. Jeśli trapi cię jakaś dolegliwość, odwiedź mojego pomocnika Bom\'baya, tu za mną. Jego wudu jest silne...', 0),
(827, 'koKR', 'Dobrze. W tych kołnierzach kryje się sekret Płonącego Ostrza. I ja ten sekret odkryję...', 0),
(828, 'koKR', 'Witaj, $N. Doszły mnie wieści o twoim przybyciu i o twoich wyczynach w Durotarze.$b$bTwoje umiejętności i sława wciąż rosną.$b$bTrzymaj się czystej ścieżki, a czeka cię naprawdę wielka przyszłość.', 0),
(829, 'koKR', 'Ach, a skąd to masz? Przysłał cię do mnie dobry Margoz z Brzytwogóry, tak?$b$bCóż, przyjrzyjmy się temu bliżej...', 0),
(830, 'koKR', 'To nie wróży nic dobrego. Mądrze $gzrobiłeś:zrobiłaś;, przynosząc mi te informacje.', 0),
(831, 'koKR', 'Niezliczoną ilość razy namawiałem wodza, by nie ufał ludziom, ale nie o osobistą dumę tu chodzi.$b$bHonorowo $gsłużyłeś:służyłaś; Hordzie, $N.$b$bA teraz wybacz, muszę natychmiast naradzić się z Thrallem w tych sprawach...', 0),
(832, 'koKR', '<Ogląda Oko Płonącego Cienia>$b$bIntrygujące. Głos, który $gusłyszałeś:usłyszałaś;, wymienił moje imię? Słynę z tropienia wrogów naszego wodza, ale... dziwne, że wskazano akurat mnie. Jeszcze dziwniejsze, że kultyści Płonącego Ostrza, od których $godzyskałeś:odzyskałaś; ten wisior, noszą nazwę tak podobną do mojego imienia.$b$bMuszę zbadać ten wisior. Muszę go zbadać i zastanowić się nad znaczeniem jego przesłania.$b$bDziękuję, że $gzwróciłeś:zwróciłaś; mi na to uwagę, $N. $GOddałeś:Oddałaś; swojemu ludowi wielką przysługę.', 0),
(834, 'koKR', 'No proszę, tego mi było trzeba! $GOdzyskałeś:Odzyskałaś; nasze zapasy. Super. Wrócę do roboty, jak tylko znajdę kogoś, kto mi przydźwiga te worki.', 0),
(835, 'koKR', 'Chyba mogę wreszcie odetchnąć, wiedząc, że harpie nie będą już nękać naszych karawan z zaopatrzeniem. I to w ostatniej chwili. Słyszałem, że z następną dostawą przyślą mi parę fajnych zabawek!$B$BZnasz się na rzeczy, $N. Warto, żebyś $godszukał:odszukała; mojego szefa w Zapadce. Założę się, że znalazłby dla ciebie jakąś robotę.$B$BAch, i spokojna głowa, nie zapomniałbym zapłacić ci za przysługę.', 0),
(837, 'koKR', 'Przekażę wieść, że kolcozwierze zostały wygnane ze swoich legowisk, a ich budowle można podpalić. Wypędzenie Brzytwogrzywych z Durotaru przybliża nas do pełnego zabezpieczenia granic naszej nowej ojczyzny.', 0),
(840, 'koKR', 'O, to Takrin cię przysłał? Świetny z niego zwiadowca, nie wiem, co bym bez niego zrobił.$b$bPodpiszę twój list werbunkowy, ale tak naprawdę potrzebujemy kogoś na Rozdrożu.', 0),
(842, 'koKR', 'Dobra, $N. Chcesz zarobić na swoje utrzymanie w Hordzie? Roboty tu nie brakuje, więc słuchaj uważnie i rób, co ci każą.$b$b$gWidzę to spojrzenie w twoich oczach – nie myśl, że zniosę jakąkolwiek bezczelność. Sam Thrall ogłosił, że kobiety Hordy są na równi z wami, mężczyznami. Okaż mi choć odrobinę braku szacunku, a poznasz prawdziwy ból.:Cieszę się, że cię poznałam. Thrall ucieszy się, wiedząc, że coraz więcej kobiet takich jak my bierze sprawy w swoje ręce i prze naprzód na Pustkowiach.;', 0),
(924, 'koKR', 'Twoje zadanie wykonane. $GZniszczyłeś:Zniszczyłaś; Demoniczne Nasiono, tak jak chciał Neeru. Ale to nie koniec...$b$bZniszczenie Demonicznego Nasiona posłało przez eter fale mocy, fale oszałamiającej siły. Poczułem je i jestem pewien, że inne istoty też je poczuły. Istoty, które zaczną się zastanawiać, kto zepsuł im zabawkę...$b$bAle bez względu na przyszłe kłopoty mam coś dla ciebie. Neeru przysłał to jako zapłatę. I kazał ci podziękować.$b$bWięc dziękuję.', 0),
(926, 'koKR', 'Te kamienie są nasycone magiczną energią, ale celowo uczyniono je wadliwymi. Są bardzo niestabilne i zdjęte ze stołu szybko same się wypalą.', 0),
(1463, 'koKR', 'Daję ci jedną w dobrej wierze. Raz już się $gwykazałeś:wykazałaś;, ale ja tam myślę, że na przyszłość $gpowinieneś:powinnaś; bardziej uważać.', 0),
(1464, 'koKR', 'Niech ogień płonie w twoim sercu, $N.$B$BŻywioły na ciebie czekają.', 0),
(1499, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N.$b$bChoć plugawe chowańce były jedynie pupilkami mroczniejszych mocy Płonącego Ostrza, twój sukces w walce z nimi zapowiada większe czyny.', 0),
(1505, 'koKR', 'Witaj, $gmłodzieńcze:młoda;. $GPrzyszedłeś:Przyszłaś; po naukę, co?', 0),
(1506, 'koKR', 'Dobrze. Obawiałem się, że Ophek do ciebie nie dotrze.$B$BPora, bym poprowadził dalej twoje czarnoksięskie szkolenie. Wszystkie twoje obecne sprawy muszą poczekać.$B$BUfam, że nie będzie z tym problemu?', 0),
(1516, 'koKR', 'Doskonale. Twój sukces pokazuje, że jesteś $gprzygotowany:przygotowana;.$B$BSpośród wszystkich żywiołów to ziemia jest fundamentem wszystkiego. Jest twoją siłą, twoją wytrzymałością i twoją cierpliwością. Ziemia będzie cię chronić, ale tylko wtedy, gdy okażesz jej należny szacunek. Jak inne żywioły, nawet ziemia bywa kapryśna. Ziemia jest podstawą życia, a przestrzegając jej praw, zyskasz większą mądrość. Nigdy nie zapominaj tajemnic, które ziemia ci powierza.$B$BTeraz przygotuję dla ciebie saptę, a gdy ją przyjmiesz, pojmiesz swoją ścieżkę.', 0),
(1517, 'koKR', 'Ach... $N... ziemia raduje się, że tu jesteś.$B$B$GZwiązany:Związana; z nami ciałem i duchem, pójdziesz naprzód, wiedząc, że góry są twoją siłą, równiny twoją cierpliwością, a sam świat twoją istotą.$B$BBy przejść ten rytuał, wystarczy, że pokornie staniesz przed ziemią. Ale inne żywioły nie są tak bierne. Bywają chaotyczne i często gwałtowne, lecz taka jest natura żywiołów. Dwoiste natury, które sobie przeciwstawiają – musisz je dogłębnie poznać.', 0),
(1518, 'koKR', 'Doskonale!$B$BTotem, który dla ciebie wykonam, to coś więcej niż symbol twojej pozycji wśród szamanów – kryje też inne moce. Może między innymi służyć jako skupienie dla zaklęć. Te zaklęcia są związane z ziemią, a w miarę jak będziesz zdobywać coraz większą mądrość, coraz więcej mocy ziemi stanie przed tobą otworem.$B$BNauczyciele będą wiedzieć, kiedy jesteś $ggotów:gotowa; na głębszą wiedzę.$B$BNa razie jednak weź ten totem ziemi i zwój, który nauczy cię pierwszej umiejętności.', 0),
(1520, 'koKR', 'Ach... $N... ziemia raduje się, że tu jesteś.$B$B$GZwiązany:Związana; z nami ciałem i duchem, pójdziesz naprzód, wiedząc, że góry są twoją siłą, równiny twoją cierpliwością, a sam świat twoją istotą.$B$BBy przejść ten rytuał, wystarczy, że pokornie staniesz przed ziemią. Ale inne żywioły nie są tak bierne. Bywają chaotyczne i często gwałtowne, lecz taka jest natura żywiołów. Dwoiste natury, które sobie przeciwstawiają – musisz je dogłębnie poznać.', 0),
(1521, 'koKR', 'Wspaniale.$B$BTotem, który dla ciebie wykonam, to coś więcej niż symbol – kryje też inne moce. Może między innymi służyć jako skupienie dla zaklęć. Te zaklęcia są związane z ziemią, a w miarę jak będziesz zdobywać coraz większą mądrość, coraz więcej mocy ziemi stanie przed tobą otworem. Nauczyciele w całym Kalimdorze będą wiedzieć, kiedy jesteś $ggotów:gotowa; na głębszą wiedzę, i dadzą ci znać, gdy ich odwiedzisz.$B$BNa razie jednak weź ten totem ziemi i zwój, który nauczy cię pierwszej umiejętności.', 0),
(1524, 'koKR', 'Ach, mój błąd, $N. Przepraszam. Nie wiedziałem, że masz Pochodnię. Miło mi cię poznać.$B$BWielu poszukiwaczy przygód trafia tu w pogoni za zaginionym skarbem albo w nadziei na ubicie mistycznych stworzeń, a potem odchodzi z niczym sprzed pozornie pustej kaplicy. Ale my znamy prawdę, czyż nie, $N?$B$BTa kaplica skrywa przed zwykłymi członkami Hordy głębszą tajemnicę. Dla nas jest święta.', 0),
(1525, 'koKR', 'Doskonale się nadadzą, $N.$B$BOgień to coś więcej niż chaos i zniszczenie – dobrze to zapamiętaj. To także życie i tworzenie. Wszystko jest ze sobą w ten sposób powiązane. Siły sobie przeciwstawiają, lecz zarazem jedna nie może istnieć bez drugiej. Wzajemnie się gaszą, ale też nadają sobie sens. Zawsze o tym pamiętaj.$B$BŁączenie różnych rodzajów magii świadczy nie tylko o prawdziwym kunszcie, ale i o wielkiej mądrości.', 0),
(1526, 'koKR', 'Gdy kładziesz węgielek w misie, rozpala się w niej białożarny płomień. Czujesz, jak magiczna moc sapty krąży w twoim ciele, a ogień rytmicznie tańczy przed tobą.$B$BWkładasz głowicę pochodni do misy i ta natychmiast zajmuje się ogniem.', 0),
(1527, 'koKR', 'Twój duch płonie jaśniej niż jakakolwiek pochodnia, jaką w życiu widziałem, $N, i możesz być z tego $gdumny:dumna;.$B$BJeśli dalej będziesz podążać tą ścieżką, żywioły staną się ci posłuszne, a nasi bracia będą szukać u ciebie przewodnictwa i mądrości. Pozwól, że jako pierwszy ci pogratuluję i wręczę ci twój najnowszy totem.', 0),
(1528, 'koKR', 'Wiatr szybko nadciąga ku tobie od horyzontu, ziemia stoi pewnie pod twoimi stopami, a twojego ducha ogrzał już ogień – powiedziałabym, że czas, byś $gpoznał:poznała; czystość wody.$B$BTwoja ścieżka zaprowadziła cię aż tutaj, a duch da ci siłę, by iść jeszcze dalej. Ale pierwszy krok należy do ciebie.', 0),
(1529, 'koKR', 'Wiatr szybko nadciąga ku tobie od horyzontu, ziemia stoi pewnie pod twoimi stopami, a twojego ducha ogrzał już ogień – powiedziałabym, że czas, byś $gpoznał:poznała; czystość wody.$B$BTwoja ścieżka zaprowadziła cię aż tutaj, a duch da ci siłę, by iść jeszcze dalej. Ale pierwszy krok należy do ciebie.', 0),
(1839, 'koKR', 'Witaj, $N. Stary Thun\'grim uprzedził mnie o twoim przybyciu, ale nawet gdyby milczał, twoja obecność by mnie nie zaskoczyła.$B$BDuchy śledzą twoje postępy, $gmłody wojowniku:młoda wojowniczko;, i mówią mi, że wielu wrogów padło przed tobą.', 0),
(1842, 'koKR', 'Ach, masz je! Teraz, tak jak satyry wysysały siłę Jesionowej Kniei, ja wyssę moc zamkniętą w tych kopytach i włożę ją w swoją robotę...', 0),
(1843, 'koKR', 'Dziękuję ci, $N. Te rękawice to moje najlepsze dzieło. Weź je. Nosząc je, przynosisz chwałę mnie i moim przodkom.', 0),
(1859, 'koKR', 'Bardzo dobrze. Cieszę się, że Kaplakowi udało się ciebie złapać.$b$bMamy parę spraw do omówienia, a jedna z najważniejszych to twoja przyszłość w Strzaskanej Dłoni.', 0),
(1883, 'koKR', 'Witaj, $N. Chwała ci, bo moje wołanie o pomoc zostało wysłuchane. Miejmy nadzieję, że podołasz zadaniu...', 0),
(1884, 'koKR', 'Czuję, że Zalazane stracił swoje stosy juju. Z czasem, przy odrobinie szczęścia, przepływ magii w Durotarze wróci do normy.$b$bWielki czyn $gspełniłeś:spełniłaś; dla swojego ludu, $N. I $gpokazałeś:pokazałaś; nam, magom Hordy, ile jesteś $gwart:warta;.', 0),
(1959, 'koKR', 'To prawda. W naszym mieście wykryto zakłócenie magii. Nie wiemy jeszcze, skąd się wzięło ani czy jest złowrogie, czy nieszkodliwe. Najpierw musimy zebrać więcej informacji...$B$BI tu, $N, dochodzimy do twojego zadania.', 0),
(2161, 'koKR', 'Ach, to jedzenie, które Ukor zaniósł do Doliny Prób. Nie było im potrzebne? No cóż, chyba lubią głodzić was, bohaterów na szkoleniu. Mówią, że to hartuje ducha!$b$bDzięki, że $godniosłeś:odniosłaś; jedzenie. Wstawię je z powrotem na półki... ale najpierw pozwól, że cię czymś poczęstuję!$b$bI nie zapomnij odpocząć tu, w gospodzie. Może i jesteś $godważny:odważna; i $ggotów:gotowa; rzucić wyzwanie całemu światu, ale jeśli opadniesz z sił, nie zdziałasz wiele ani dla siebie, ani dla Hordy.', 0),
(2380, 'koKR', 'To ważne, by Strzaskana Dłoń zachowała czujność wobec zmian, które Thrall chce wprowadzić w Hordzie. Sama liczebność nie wystarczy, by obalić jego rządy – musimy opanować skradanie i podstęp.', 0),
(2383, 'koKR', 'Ach, to mój pergamin. Słyszałem, że przybędziesz do Doliny, $N. Cieszę się, że $gdotarłeś:dotarłaś; – miejmy nadzieję, że przetrwasz czekające cię próby. Jak pisałem, gdy będziesz rosnąć w siłę, przychodź do mnie – zrobię, co w mojej mocy, by wyszkolić cię w sztuce wojownika.$b$bPowodzenia, $N. Wracaj do mnie, kiedy tylko poczujesz się $ggotów:gotowa;.', 0),
(2935, 'koKR', 'Ach, więc chcesz świeżego jadu pająka Suchokorych, tak? No to siadaj... nie spodoba ci się to, co mam do powiedzenia.', 0),
(2936, 'koKR', 'Ach, Elortha no Shadra... wypowiadaj to imię tylko szeptem, bo w królestwach duchów niesie ono wielką moc.$b$bSpiszę je na pergaminie i stworzę dla ciebie zaklęcie przyzwania...', 0),
(2937, 'koKR', 'Świetnie, masz go!', 0),
(2983, 'koKR', 'Hmm, Swart cię do mnie przysłał, tak?$B$BCóż, Swartowi zawsze można było ufać, więc musisz być $ggotów:gotowa; na kolejną saptę – saptę ognia.$B$BJuż widzę to w twoich oczach: ten żar, to pragnienie. $GPosmakowałeś:Posmakowałaś; mocy, a teraz chcesz więcej. Cierpliwości, $N. Pamiętaj, czego nauczyła cię ziemia. Moc i zniszczenie przyjdą łatwo, ale wciąż musisz wiedzieć, kiedy powstrzymać rękę.', 0),
(2985, 'koKR', 'Wiatr szybko nadciąga ku tobie od horyzontu, ziemia stoi pewnie pod twoimi stopami, a twojego ducha ogrzał już ogień – powiedziałabym, że czas, byś $gpoznał:poznała; czystość wody.$B$BTwoja ścieżka zaprowadziła cię aż tutaj, a duch da ci siłę, by iść jeszcze dalej. Ale pierwszy krok należy do ciebie.', 0),
(2986, 'koKR', 'Wiatr szybko nadciąga ku tobie od horyzontu, ziemia stoi pewnie pod twoimi stopami, a twojego ducha ogrzał już ogień – powiedziałabym, że czas, byś $gpoznał:poznała; czystość wody.$B$BTwoja ścieżka zaprowadziła cię aż tutaj, a duch da ci siłę, by iść jeszcze dalej. Ale pierwszy krok należy do ciebie.', 0),
(3065, 'koKR', 'Przekonasz się, że to miejsce dobrze ci posłuży, gdy będziesz dalej szkolić się na wojownika. Jeśli masz jakieś pytania, śmiało pytaj kogokolwiek w okolicy, a gdy poczujesz się $ggotów:gotowa;, wróć do mnie na szkolenie. Opanowałem sztukę wojownika jak mało kto w tej Dolinie i mogę przekazać ci tę wiedzę... za opłatą.', 0),
(3082, 'koKR', 'Teraz my uczymy ich tych rzeczy, a oni uczą nas innych. Stajemy się jedną rasą... prawie. Od dawna już jesteśmy sojusznikami. Więc ty pamiętaj, żeby im pomagać. A Jen\'shan będzie pamiętać, żeby pomagać tobie.$b$bJen\'shan nauczy cię dróg łowcy – nauczy cię dobrze. Nigdy nie zapominaj, że łowcy są w plemieniu bardzo szanowani. Masz do odegrania wielką rolę w przyszłości... nigdy o tym nie zapominaj.$b$bKiedy poczujesz potrzebę, przyjdź do Jen\'shan. Ona nauczy cię tyle, ile może, kiedy uzna, że jesteś $ggotów:gotowa;.', 0),
(3083, 'koKR', 'Do tego czasu będziesz pod moją opieką. Pokażę ci, co i jak, jak to mówią. Kiedy tylko poczujesz się $gprzygotowany:przygotowana;, przyjdź do mnie, a zobaczę, jak cię dalej szkolić. Do tego czasu ćwicz swoje umiejętności i dbaj, by były ostre jak brzytwa. Nigdy nie wiesz, kiedy przyda ci się nawet najdrobniejsza zdolność.', 0),
(3084, 'koKR', 'Jak pewnie wiesz, to żywioły dają nam moc. Ogień, ziemia, woda i powietrze – to nasze narzędzia.$b$bNasza siła pochodzi od duchów przodków. Jesteśmy przywódcami naszego ludu. Czym Thrall jest dla Hordy, tym my będziemy dla wiosek i osad, które odwiedzamy. Będą szukać u nas mądrości i ochrony. By być lepiej $gprzygotowanym:przygotowaną;, musisz często ćwiczyć. Kiedy poczujesz, że $gzyskałeś:zyskałaś; więcej mocy, przyjdź do mnie, a nauczę cię tego, co potrafię.', 0),
(3085, 'koKR', 'Wystawiając się na próby, zobaczysz, że coraz lepiej panujesz nad duchami – będziesz je wzywać do coraz większych rzeczy... i wtedy wkracza stary Ken\'jai. Przyjdź pogadać ze starym Ken\'jaiem, kiedy poczujesz się $ggotów:gotowa;. Jeśli duchy się zgodzą, to zobaczymy, czy nauczyć cię potężniejszych zdolności... ale tylko jeśli duchy się zgodzą.$B$BIdź teraz, pogadaj z resztą mieszkańców Doliny. Porozmawiaj ze mną później.', 0),
(3086, 'koKR', 'Jesteś jedną z najpotężniejszych istot na tym świecie, $N... nie ma co się spierać. I każdy to wie... dobrze wie!$B$BAle musisz uważać! Bo to nie orka, elfa czy krasnoluda $gpowinieneś:powinnaś; się bać... tylko tego, czego nie widać. Magia jest potężna. Każe ci robić rzeczy, których może wcale nie chcesz robić. Każe ci myśleć, że jesteś $gpotężniejszy:potężniejsza;, niż naprawdę jesteś. Bądź $gcierpliwy:cierpliwa;. Bądź $gmądry:mądra;.$B$BKiedy uznasz, że jesteś $ggotów:gotowa; na szkolenie, wróć do Mai\'ah. Ona nauczy cię tego, na co jesteś $ggotów:gotowa;, żaden problem.', 0),
(3087, 'koKR', 'Kiedy skończymy rozmawiać, pogadaj z resztą mieszkańców Doliny. Poproszą cię, żebyś coś dla nich $gzrobił:zrobiła;... rzeczy, które sprawdzą twoje umiejętności i nauczą cię trochę o niebezpieczeństwach tej krainy.$B$BKiedy nabierzesz doświadczenia i mądrości, będziesz potrzebować Jen\'shan, żeby pokazała ci lepsze techniki i umiejętności. Wracaj często do Jen\'shan. Powiem ci, czego mogę cię nauczyć.', 0),
(3088, 'koKR', 'Skoro już wiesz, gdzie się ukrywam, powinienem ci coś powiedzieć: Strzaskana Dłoń poprosiła mnie, żebym miał na ciebie oko. Chcą, żebym cię szkolił i przekazywał ci wszystko, czego mogą od ciebie potrzebować. Nawet jeśli na razie nie chcesz im pomagać – a tylko głupiec by nie chciał – zrobię, co mogę, żeby cię wyszkolić... za niewielką opłatą. Wracaj do mnie, kiedy tylko uznasz, że jesteś $ggotów:gotowa;, a zobaczymy, czego możesz się nauczyć.', 0),
(3089, 'koKR', 'Będziesz kanałem, przez który przemawiają nasi przodkowie. Moc żywiołów będzie na każde twoje skinienie. Rozgromienie wrogów będzie dziecinną igraszką, a leczenie sojuszników łatwe jak oddychanie. Pamiętaj o tym, gdy staniesz przed nowymi wyzwaniami, i wracaj do mnie, kiedy tylko zechcesz. Zostanę tutaj, by uczyć cię nowych zaklęć i kierować cię na właściwą ścieżkę, gdy będziesz $ggotów:gotowa;.', 0),
(3090, 'koKR', 'A teraz i ty $gdołączyłeś:dołączyłaś; do naszych szeregów. Nie zrozum mnie źle, $n. To, że masz dostęp do mocy, której wielu będzie ci zazdrościć, nie znaczy, że łatwo cię zaakceptują. Thrall wpuszcza nas do Orgrimmaru, bo wciąż jesteśmy jego pobratymcami – nie może się od nas odwrócić, inaczej stalibyśmy się równie żałośni jak ludzie, którzy go zniewolili. Chodzi mi o to: uważaj. Możesz być $gpotężny:potężna;, ale głupota szybko zaprowadzi cię do grobu.$B$BJeśli potrzebujesz szkolenia w zaklęciach, wróć do mnie.', 0),
(4402, 'koKR', 'Wspaniale, $N! Tak jak obiecałem, oto twoja niespodzianka z kaktusowego jabłka i jeszcze coś ekstra.', 0),
(4641, 'koKR', 'Kolejny rekrut Kaltunka, co?$B$BMarny nasz los, jeśli to najlepsze, na co stać Hordę. Nieważne. Zanim uznamy, że możesz opuścić Dolinę, staniesz się chlubą Hordy.', 0),
(5441, 'koKR', 'Dobrze, dobrze. Może następnym razem zastanowią się dwa razy, zanim zaczną się obijać! Dzięki za pomoc!', 0),
(5648, 'koKR', 'Dobrze, a więc Kor\'ja żyje i wraca bronić naszej osady przed tymi podłymi ludźmi. Często tęsknię za dniami bitew, gdy moc okazywało się w walce, a to mądrzy często niszczyli tych, którzy polegali wyłącznie na sile.$B$BDobrze mi się $gprzysłużyłeś:przysłużyłaś;, $N. Weź teraz tę szatę. Może się przyda, może nie będzie cię obchodzić, ale $gzasłużyłeś:zasłużyłaś; na nią, a ja z dumą nazywam cię $gbratem:siostrą;.', 0),
(5649, 'koKR', 'Ach... więc w końcu $gprzyszedłeś:przyszłaś; do Tai\'jin. To dobrze.$B$BWiesz już, że nie jesteśmy tym samym plemieniem, które kiedyś przyłączyło się do Hordy. Jesteśmy teraz znacznie silniejsi. Silniejsi, bo się przystosowujemy – tego przynajmniej nauczyła nas Horda. Już nie pokonujemy wrogów, by czerpać z nich siłę; teraz nabieramy siły, a potem pokonujemy wrogów.$B$BRóżnica jest subtelna, ale zrozumiesz ją. Przekonasz się. Plemię liczy na to, że się tego nauczysz.', 0),
(6062, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Sądzę, że jesteś $ggotów:gotowa; na kolejne zadanie.', 0),
(6065, 'koKR', 'Tak, sądzę, że jesteś $ggotów:gotowa;...', 0),
(6066, 'koKR', 'Tak, sądzę, że jesteś $ggotów:gotowa;...', 0),
(6067, 'koKR', 'Tak, sądzę, że jesteś $ggotów:gotowa;...', 0),
(6068, 'koKR', 'Tak, czas zacząć twoje szkolenie.', 0),
(6069, 'koKR', 'Tak, czas zacząć twoje szkolenie.', 0),
(6070, 'koKR', 'Tak, czas zacząć twoje szkolenie.', 0),
(6081, 'koKR', '$GMłody łowca:Młoda łowczyni;, jak widzę. Tak, przekażę ci umiejętności potrzebne do szkolenia i prowadzenia twojego zwierzęcia. Nie tylko zdołasz uczyć je nowych zdolności – odtąd możesz je też karmić, a nawet wskrzesić, jeśli padnie w walce.$B$BA teraz idź, $N. Porozmawiamy znowu, w swoim czasie.', 0),
(6082, 'koKR', 'Nauczyłem cię wszystkiego, czego mogłem, $N. Czas, byś $gwykorzystał:wykorzystała; to, czego się tu $gnauczyłeś:nauczyłaś;, i $gwybrał:wybrała; własne zwierzę.$B$BProszę, $N. Daję ci teraz moc oswajania bestii, a także przywoływania ich i odsyłania, jak uznasz za stosowne. Korzystaj z nowych umiejętności z dumą; $gzasłużyłeś:zasłużyłaś; na nie.', 0),
(6083, 'koKR', 'Szybko się uczysz, $N. Dobrze się $gspisałeś:spisałaś;.', 0),
(6394, 'koKR', 'Świetnie, masz go! Wielkie dzięki, $N. To mój ulubiony kilof! Jeśli moje peony kiedyś skończą ścinać te drzewa, może znajdziemy jakąś porządną jaskinię do kopania!', 0),
(8150, 'koKR', 'Pełne imię Groma – Grommasz – znaczy „Serce Olbrzyma”; trzeba było takiego serca, a nawet czegoś więcej, by samotnie stanąć przeciw Mannorothowi. Chyba najlepiej ujął to wódz: klątwa orków zaczęła się i skończyła na Gromie. To słuszne, że ofiara Groma – a może i jego odkupienie – stała się źródłem, z którego wypływa dzisiejsza Horda.$B$BDziękuję, $N. $GOddałeś:Oddałaś; dziś hołd wielkiemu bohaterowi i $guczciłeś:uczciłaś; jego ducha oraz ducha Dożynek.', 0),
(8358, 'koKR', 'Tuu-tuu! Dobra robota, $N! Oto twój smakołyk.$B$BWesołych Zaduszników!', 0),
(8609, 'koKR', 'Świetnie, masz go!', 0),
(8670, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8672, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8673, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8674, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8675, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8678, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8679, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8682, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8683, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8685, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(8686, 'koKR', 'W twoim duchu płonie życie, $N. Przyjmuję hołd, który składasz, i w zamian ofiarowuję ten dar...', 0),
(9617, 'koKR', '$N, dobrze, że $gprzybyłeś:przybyłaś;. Nasza lista sojuszników się kurczy, a nawet tym, którzy dzielą naszą sprawę, nie można w pełni ufać. Dlatego my, tropiciele, zwracamy się o pomoc do natury.$B$BW sojusznikach z lasu znajdujemy głęboką więź, która nie zna podstępu.', 0),
(10529, 'koKR', '$N, dobrze, że $gprzybyłeś:przybyłaś;. Nasza lista sojuszników się kurczy, a nawet tym, którzy dzielą naszą sprawę, nie można w pełni ufać. Dlatego my, tropiciele, zwracamy się o pomoc do natury.$B$BW sojusznikach z lasu znajdujemy głęboką więź, która nie zna podstępu.', 0),
(10530, 'koKR', '$N, dobrze, że $gprzybyłeś:przybyłaś;. Nasza lista sojuszników się kurczy, a nawet tym, którzy dzielą naszą sprawę, nie można w pełni ufać. Dlatego my, tropiciele, zwracamy się o pomoc do natury.$B$BW sojusznikach z lasu znajdujemy głęboką więź, która nie zna podstępu.', 0),
(11120, 'koKR', 'Dobra robota, $gmały:mała;. Masz, to zapłata za wykonane zlecenie.', 0),
(11219, 'koKR', 'Pożary ugaszone! Ty i twoja straż pożarna odnieśliście zwycięstwo! Ha!$B$BAtak Bezgłowego Jeźdźca się nie powiódł, ale dopóki on i jego głowa nie zostaną zniszczeni razem, będzie wracał.$B$BTymczasem jednak cieszmy się bezpieczeństwem, które $gzapewniłeś:zapewniłaś; naszym dzieciom. To dla mnie zaszczyt, że mogłam dziś oglądać twoją dzielną pracę.', 0),
(11357, 'koKR', 'Dzieci uwielbiają patrzeć na bohaterów przy pracy. Mam nadzieję, że pewnego dnia każda z tych sierot wyrośnie na silnego członka Hordy, a na koniec zginie w chwalebnej bitwie!$B$BAch, na myśl o tak pięknym losie aż łza kręci mi się w oku...', 0),
(11361, 'koKR', 'Dobra robota, $N! Dzieci, przyjrzyjcie się dobrze: oto $c. Rośnijcie na równie silnych i dzielnych, a pewnego dnia i wy będziecie walczyć za Hordę.', 0),
(11403, 'koKR', 'Co? Ta święta księga należała kiedyś do osławionego paladyna Przymierza. Czy to on był Bezgłowym Jeźdźcem? Czy to znaczy, że Jeździec został pokonany?$B$BTo chwalebny dzień, $N! Twoja legenda zajaśnieje pełnym blaskiem i oby trwała dwakroć dłużej niż lata, przez które Jeździec siał strach.', 0),
(11407, 'koKR', '$GDotrzymałeś:Dotrzymałaś; słowa i ludzie wiedzą już o naszych gorzelnikach. Dziękuję. Obiecaliśmy ci te żetony i chętnie ci je dajemy. Trolle pewnie rozstają się ze swoimi żetonami nieco mniej chętnie...$B$BWróć innego dnia, by pomóc nam dalej głosić wieść o Festiwalu Piwa.', 0),
(11408, 'koKR', 'Udało ci się! Musimy się szykować na zalew klientów, którzy na pewno do nas ściągną! Dzięki!$B$BA, racja, obiecaliśmy ci nagrodę. Nie można o tym zapomnieć...$B$BŚmiało, wpadnij innego dnia i pomóż nam jeszcze trochę rozgłosić wieść.', 0),
(11409, 'koKR', 'No, nieźle ci poszło... Na pewno nie jesteś krasnoludem?$b$bŚcigania będzie jeszcze sporo, i to nie tylko u mnie. Na całym terenie Festiwalu Piwa znajdziesz takich, którym przyda się ktoś, kto porządnie jeździ na baranie. Idź więc i zrób z siebie użytek.$b$bAha, i nie zapominaj: te barany zostały zdobyte legalnie. Chcę tylko mieć pewność, że się rozumiemy.', 0),
(11412, 'koKR', 'Dzięki za pomoc! Dopóki trwa Festiwal Piwa, Czarnoryci atakują, a nasz dostawca tkwi w tym kanionie, będę potrzebował pomocy przy przewożeniu beczek. Jeśli więc chcesz zapracować na więcej żetonów, zaglądaj do mnie codziennie.$B$BOto obiecane żetony. Baw się dobrze!', 0),
(11446, 'koKR', 'Co?! Darmowe piwo? Tak, tak. Chyba faktycznie obiecaliśmy, że w tym roku będziemy je rozdawać.', 0),
(11447, 'koKR', 'Co?! Darmowe piwo? Tak, tak. Chyba faktycznie obiecaliśmy, że w tym roku będziemy je rozdawać.', 0),
(11449, 'koKR', 'Dobra robota, $N. Dzieci, przyjrzyjcie się dobrze: oto $c. Niech będzie dla was wzorem siły.', 0),
(11450, 'koKR', 'Dobra robota, $N. Dzieci, przyjrzyjcie się dobrze: oto $c. Bierzcie z $gniego:niej; dobry przykład.', 0),
(11487, 'koKR', 'Czyli $godwiedziłeś:odwiedziłaś; Czarnorytych i $gpróbowałeś:próbowałaś; położyć kres ich sabotażowi, co, $gmały:mała;? Wiesz, że znów zaatakowali. Wygląda na to, że słowo Czarnorytych jest warte tyle, co ich piwo.$B$BMimo to doceniam twoją pomoc. Chyba. Masz, w nagrodę weź kufel tego „piwa”, które $gprzyniosłeś:przyniosłaś; z głębi tamtej góry. Nie, naprawdę. Przynajmniej tyle mogę zrobić.', 0),
(11770, 'koKR', 'Zbezcześć wielkie ognisko Hordy w Durotarze!', 0),
(11846, 'koKR', 'Uczcij płomień Durotaru!', 0),
(11915, 'koKR', 'Witaj. Chcesz się nauczyć nowych sposobów obchodzenia się z ogniem?', 0),
(11966, 'koKR', 'Ach, a cóż to takiego? Jakiż rozkoszny aromat! Z pewnością spłonie czystym i jasnym płomieniem!$B$BWeź ten kwiat, $N. Weź go i zostaw mnie w spokoju... Trzeba mi się zająć tym cennym paliwem...', 0),
(12139, 'koKR', 'Pożary ugaszone! Ty i twoja straż pożarna odnieśliście zwycięstwo! Ha!$B$BAtak Bezgłowego Jeźdźca się nie powiódł, ale dopóki on i jego głowa nie zostaną zniszczeni razem, będzie wracał.$B$BTymczasem jednak cieszmy się bezpieczeństwem, które $gzapewniłeś:zapewniłaś; naszym dzieciom. To dla mnie zaszczyt, że mogłam dziś oglądać twoją dzielną pracę.', 0),
(12191, 'koKR', 'O rany... S.T.O.U.T. się nie rozleciał... Hmm... Kto by pomyślał?$b$bTo znaczy, hej, udało ci się! Oko masz celne, a przynajmniej dość celne, żeby pomóc w pilnowaniu obozu. Myślę, że teraz dasz radę Czarnorytym, jeśli znów się zjawią.', 0),
(12192, 'koKR', 'Czyli udało ci się powstrzymać Czarnorytych... I to po pijanemu? Oto prawdziwy duch Festiwalu Piwa! A skoro o duchu Festiwalu Piwa mowa, to pewnie chcesz swoje żetony nagrodowe.$B$BDzięki za pomoc, $N. Baw się dobrze do końca Festiwalu Piwa.', 0),
(12194, 'koKR', 'A to co? Bon na kufel? Czyli lubisz wypić? Świetnie! Jak już dam ci ten kufel, idź się napić! Potem wypij jeszcze trochę. A po tym może jeszcze parę kolejek... A potem, i to ważne, przyjdź do mnie.$b$bSłuchaj, wiem, że w końcu wrócisz. Jeśli chcesz wymienić swoje żetony Festiwalu Piwa, musisz przyjść do mnie.$b$bTak czy siak, oto kufel. I pamiętaj, żeby potem ze mną pogadać.', 0),
(12492, 'koKR', 'Ach, więc Bimberhaust wreszcie zgłosił swoje piwo. Szkoda, że musiał przy tym zginąć...$B$BNo cóż. Do dna, co?', 0),
(13931, 'koKR', 'A to co? Bon na kufel? Czyli lubisz wypić? Świetnie! Jak już dam ci ten kufel, idź się napić! Potem wypij jeszcze trochę. A po tym może jeszcze parę kolejek... A potem, i to ważne, przyjdź do mnie.$b$bSłuchaj, wiem, że w końcu wrócisz. Jeśli chcesz wymienić swoje żetony Festiwalu Piwa, musisz przyjść do mnie.$b$bTak czy siak, oto kufel. I pamiętaj, żeby potem ze mną pogadać.', 0),
(14040, 'koKR', 'Placek zawsze znika pierwszy. Ludzie chyba pomijają posiłek i od razu rzucają się na deser. $GPróbowałeś:Próbowałaś; go już?', 0),
(14041, 'koKR', 'Ach, jeszcze więcej żurawinowego chutney! Nie uwierzysz, jak szybko znika ono z talerzy biesiadników.', 0),
(14043, 'koKR', 'Czyli Dokin zaciągnął cię do pomocy przy kandyzowanych batatach?$B$B<Francis się uśmiecha.>$B$BTylko tak jest w stanie nadążyć. Dzięki, że je $gprzyniosłeś:przyniosłaś;.', 0),
(14044, 'koKR', 'Dzięki, że wszystko $gprzyniosłeś:przyniosłaś;. Na niektórych stołach zaczynało już brakować półmisków.', 0),
(14047, 'koKR', 'Wyglądają idealnie. Dziękuję, $N. Wszystkie dania tradycyjnego posiłku na Dary Pielgrzymów masz już w małym palcu.', 0),
(14061, 'koKR', 'Tych indyków właśnie mi było trzeba. Dzięki, że $gwybawiłeś:wybawiłaś; mnie z opresji.', 0),
(14062, 'koKR', 'W samą porę! Bez farszu z chleba z przyprawami nie mogłabym podać uczty.', 0),
(25343, 'koKR', 'Teraz, gdy rozumiesz plan Mistrza, musisz przygotować się do odegrania w nim swojej roli.', 0),
(25380, 'koKR', 'Dobra robota, $N. Z początku może być niezręcznie, ale przywykniesz do publicznego głoszenia naszej wiary. To jeden ze sposobów, by pamiętać o naszym obowiązku niesienia prawdy innym. Musimy ocalić tylu, ilu zdołamy.', 0),
(25444, 'koKR', 'Tyle mi wystarczy. Teraz zaczyna się trudniejsza część.', 0),
(25445, 'koKR', '$N, jesteś $gpotężnym wojownikiem i zaciekłym towarzyszem:potężną wojowniczką i zaciekłą towarzyszką; dla trolli Mrocznej Włóczni. Wyspy Echa są teraz NASZE i bez ciebie byśmy tego nie dokonali.$B$BWeź ten płaszcz. Noś go z dumą. Należysz teraz do plemienia!$B$BWkrótce trolle znów będą miały dom, a zawdzięczamy to tobie.', 0),
(25446, 'koKR', 'Już zaczynam widzieć to, co widzą żaby. Wszystko $gzrobiłeś:zrobiłaś; idealnie, $N. Teraz Vol\'jin i ja zobaczymy, co knuje Zalazane.', 0),
(25461, 'koKR', '$GZnalazłeś:Znalazłaś; kilku dobrych. Dam im porządnie w kość i nie spoczniemy, dopóki nie przepędzimy Zalazanego z naszych wysp.', 0),
(25470, 'koKR', 'Więc żaby Vaniry mówią prawdę? Ta tygrysica to druidka i sojuszniczka? Nie mogliśmy liczyć na lepszy obrót spraw. To dobry znak przed nadchodzącą bitwą.', 0),
(25480, 'koKR', 'Wezmę sobie rady duchów do serca. Z nimi za plecami i z mocą pradawnych loa plemienia Mrocznej Włóczni jesteśmy gotowi odebrać to, co nasze!', 0),
(25495, 'koKR', 'Wreszcie wszystko gotowe. Teraz pokażemy Zalazanemu, co spotyka tych, którzy sprzeciwiają się Mrocznej Włóczni!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(784, 'koKR', 'Masz swoje rozkazy, $N. Bezpieczeństwo Durotaru stoi pod znakiem zapytania. Wykonaj zadanie albo zwieś głowę ze wstydu.$B$BOkaż swój honor i pokonaj ludzi z Twierdzy Tiragarde.', 0),
(786, 'koKR', 'Centaury od dawna dają się Hordzie we znaki. Nie możemy tolerować ich zamiarów oblężenia naszej ojczyzny.', 0),
(788, 'koKR', 'Chyba nie $gwróciłeś:wróciłaś; po to, żeby mnie przekonywać, że zadanie wykonane, $N? Nie, oczywiście, że nie. Spodziewałbym się po tobie więcej.', 0),
(789, 'koKR', 'Pancerz skorpiady nie jest tak gruby, by oprzeć się sile zdeterminowanego wojownika. Uderzaj mocno i bez wahania, a skorpiady okażą się łatwą zdobyczą.', 0),
(790, 'koKR', 'Ach... ojciec zawsze mówił, że nic ze mnie nie będzie, a teraz, gdy leżę pod drzewem i uchodzi ze mnie życie, obawiam się, że miał rację.$b$bChcę przynajmniej umrzeć ze świadomością, że mój ostatni wróg leży martwy.', 0),
(791, 'koKR', 'Walczyłem dumnie u boku wodza, gdy zdobywaliśmy te ziemie. Moją skórę znaczą blizny z bitew.$b$bGdy pokonaliśmy Archimonda, a z konieczności zawarto bezbożny sojusz z ludźmi i elfami, mój topór i mój okrzyk bojowy pomogły obronić honor Hordy.$b$bAle rola strażnika i żywiciela dała mi nowe poczucie własnej wartości.', 0),
(792, 'koKR', 'Aby dowieść swej wartości w walce z Płonącym Ostrzem, musisz najpierw pokonać jego plugawe chowańce. Wróć do mnie, gdy to zrobisz.', 0),
(794, 'koKR', 'Czy twoje zadanie jest wykonane, $N? Masz Medalion Płonącego Ostrza?', 0),
(806, 'koKR', '$GZnalazłeś:Znalazłaś; Fizzle\'a, $N? On i reszta Płonącego Ostrza muszą zostać wymieceni z naszych ziem!', 0),
(808, 'koKR', 'Masz czaszkę mojego brata, $N? Czy jest wreszcie wolny?', 0),
(812, 'koKR', 'Prawie się cieszę, że w tym stanie nie mogę wrócić do Sen\'jin. Z mojej słabości i głupoty na pewno by się naśmiewali.', 0),
(813, 'koKR', 'Pamiętaj: bez względu na to, na jakie stworzenie polujesz, dobrze zrobisz, jeśli je zbadasz i zrozumiesz jego zachowanie. Ta wiedza może ocalić ci życie.', 0),
(815, 'koKR', 'Śniadanie, obiad, kolacja! Kogo obchodzi, który to posiłek? I tak ktoś musi go ugotować – a konkretnie ja!', 0),
(816, 'koKR', 'Modlę się, by Kron do mnie wrócił, ale jestem niemal pewna, że już znam jego los.', 0),
(817, 'koKR', 'Pamiętam moje pierwsze polowanie na tygrysa, $N. Wybrałem największą z Wysp Echa i niemal cały dzień siedziałem bez ruchu w cieniu jej zarośli... obserwując... czekając.$b$bMięśnie miałem napięte i byłem gotów do skoku. To było jedno z moich największych zwycięstw, gdy tygrys w końcu połknął przynętę.', 0),
(818, 'koKR', 'Czas to prawdziwa próba twojej siły i woli. Strać cierpliwość albo ulegnij słabości, a pokażesz, kim naprawdę jesteś.', 0),
(825, 'koKR', 'Gdy dowiemy się, jak ludzie obsługują te swoje dziwne maszyny, będziemy mieć większe szanse, by pokonać ich w przyszłych bitwach.$b$bDzięki nowo zdobytej wiedzy Horda może tylko rosnąć w siłę.', 0),
(826, 'koKR', 'Czy Zalazane został pokonany, $N?', 0),
(827, 'koKR', '$GWszedłeś:Weszłaś; już do Skały Czaszki, $N? Masz palące kołnierze?', 0),
(829, 'koKR', 'Moje najpokorniejsze pozdrowienia. W czym mogę dziś pomóc $gmojemu bratu:mojej siostrze;?', 0),
(830, 'koKR', 'Widzę niepokój na twojej twarzy, $N. Co tam masz?', 0),
(831, 'koKR', 'Nie widzisz, że jestem zajęty? Mam nadzieję, że to coś pilnego...', 0),
(832, 'koKR', 'Masz do przekazania coś ważnego. Wyczuwam to w twoich oczach.', 0),
(834, 'koKR', 'Nie zrozum mnie źle, jestem świetny w tym, co robię, ale to jakiś absurd! Co mam robić, budować zamki z piasku?', 0),
(835, 'koKR', 'Po takim gościu jak mój szef Gazol byś się tego nie spodziewał, ale on zawsze wiedział, co jest grane. „Nie bój się zrobić dużego kroku”, mówił.$B$BHarpie nie przestaną nas nękać, a karawany nie przestaną być napadane, dopóki czegoś z tym nie zrobimy, co?', 0),
(837, 'koKR', 'Choć mają trochę rozumu i jakąś organizację, wciąż zdumiewa mnie, że kolcozwierze zdołały zająć i utrzymać tak wielkie terytorium w Kalimdorze. Może są bardziej przebiegłym wrogiem, niż sądzę...', 0),
(840, 'koKR', 'Czego chcesz, szczeniaku? Jeśli nie $gprzyszedłeś:przyszłaś; się zaciągnąć, nie mam dla ciebie czasu.', 0),
(842, 'koKR', 'No, no, no, kogo my tu mamy? Kargal uznał, że zasługuję na kolejnego rekruta?', 0),
(924, 'koKR', 'Demoniczne Nasiono wciąż istnieje. Czuję jego moc...', 0),
(1463, 'koKR', 'Daję ci jedną w dobrej wierze. Raz już się $gwykazałeś:wykazałaś;, ale ja tam myślę, że na przyszłość $gpowinieneś:powinnaś; bardziej uważać.', 0),
(1464, 'koKR', 'Porozmawiaj z Telfem Joolamem, aby otrzymać kolejną saptę ognia.', 0),
(1516, 'koKR', 'Cierpliwość to największa cnota ziemi. Ziemia jest świadkiem cyklu wszystkich rzeczy: góry stają się pustyniami, a rzeki kanionami. Ziemia jest najbardziej upartym i najmądrzejszym z żywiołów i nie znosi niecierpliwości.$B$BZiemia wzywa cię teraz, bo zbliża się czas konfliktu. Gdy wrócisz do mnie z sukcesem, będziesz o krok bliżej pełni.$B$BInni będą zazdrościć ci mądrości i nienawidzić cię za własną niewiedzę.', 0),
(1518, 'koKR', 'Pragnę jako pierwszy w pełni powitać cię na pierwszej z czterech ścieżek, które zawsze będą prowadzić cię ku twemu przeznaczeniu.$B$BJeśli masz kamień, który dała ci ziemia, dam ci obiecany przez nią totem.$B$BJeśli nie, to odejdź i nie wracaj, dopóki nie odnajdziesz swojej drogi.', 0),
(1521, 'koKR', 'Witaj, $N. Nie $gwróciłbyś:wróciłabyś; do mnie, gdybyś nie $gwykonał:wykonała; zadania. Pozwól, że jako pierwsza w pełni powitam cię na pierwszej z czterech ścieżek, które na zawsze wyznaczą twoje wędrówki.$B$BJeśli masz kamień, który dała ci ziemia, dam ci obiecany przez nią totem. Jeśli nie, to współczuję ci. Pełne oddanie się żywiołom to powód do wielkiej dumy.', 0),
(1524, 'koKR', 'Witaj, $N. $GTrafiłeś:Trafiłaś; do Kaplicy Uśpionego Płomienia. Tylko ci, którzy dość dobrze znają szamańskie sztuki, poznają kiedyś tajemnice tego miejsca i drzemiącą w nim moc. Przykro mi, że $godbyłeś:odbyłaś; całą tę drogę tylko po to, by teraz zawrócić – wspinaczka tutaj wcale nie jest bezpieczna – ale jestem strażnikiem kaplicy i nie mogę pozwolić, by kręcił się tu byle kto.', 0),
(1525, 'koKR', 'Mam dość składników na saptę ognia, jeśli zdobędziesz sakiewkę na składniki i trochę ognistej smoły. Fanatycy Płonącego Ostrza noszą w tych sakiewkach komponenty do większości swoich zaklęć i zwykle mają dość tego, czego potrzebuję, więc nie będziemy musieli szukać niczego więcej.$B$BSapty zawsze przyrządza się ze składników ściśle związanych z danym żywiołem. Więzi czarnoksiężników z ogniem ułatwiają nam pracę.', 0),
(1526, 'koKR', 'Palenisko sięga ci mniej więcej do jednej trzeciej wzrostu i wygląda zwyczajnie, jeśli nie liczyć inskrypcji na gładkich metalowych prętach. Metal nie nosi śladów działania pogody, a misa na szczycie jest chłodna w dotyku.', 0),
(1527, 'koKR', 'Tak, $N? Co tam masz?', 0),
(1842, 'koKR', 'Masz te kopyta, $N? Magia w nich jest silna.', 0),
(1884, 'koKR', 'Musisz się pospieszyć, $N. Zniszcz stosy juju!', 0),
(2161, 'koKR', 'Witaj w Brzytwogórze!', 0),
(2383, 'koKR', 'Co tam masz? Pergamin? Mam nadzieję, że nie jesteś jakimś $guczonym:uczoną;...', 0),
(2936, 'koKR', 'Znasz imię bogini pająków?', 0),
(2937, 'koKR', '$GZdobyłeś:Zdobyłaś; jad?', 0),
(3065, 'koKR', 'Kolejny troll zasili nasze szeregi. Jak dla mnie może być.$b$bPewnie trudno ci będzie udźwignąć porządną broń, na przykład topór, ale włócznia jest równie dobra jak każda inna.$b$bWitaj w Dolinie Prób.', 0),
(3082, 'koKR', 'Jen\'shan widzi przed sobą $gpotężnego łowcę:potężną łowczynię;, a duchy to pochwalają.$b$bŚcieżka łowcy to jedna z naszych najstarszych dróg życia. Horda przyszła do nas, kiedy ledwo walczyła o przetrwanie w Azeroth, i poprosiła, żebyśmy ją uczyli, pokazali jej sekrety wielu rzeczy. Oni już wtedy byli silni: silni w drogach szamana, silni w drogach wojownika. Ale ścieżka łowcy nie była ich ścieżką... wtedy.', 0),
(3083, 'koKR', 'Witaj w Dolinie Prób, $n. Nie byłoby cię tu, gdybyś nie $gdostał:dostała; mojej tabliczki, więc przejdę do rzeczy.$B$BJestem Rwag i odpowiadam za szkolenie łotrzyków, złodziei i kieszonkowców tu, w Dolinie. To do mnie zwróci się Strzaskana Dłoń, jeśli nie będziesz $ggotów:gotowa; na to, co nadchodzi. Ale nie martw się, Dłoń nie będzie kontrolować każdego twojego kroku. Mądrze byłoby jednak z nimi współpracować, jeśli będą potrzebować twoich talentów.', 0),
(3084, 'koKR', 'Ach, witaj, $N. Cieszę się, że $gprzybyłeś:przybyłaś;. Moje dni stały się długie, a nawet pracowite, bo mam tylu uczniów, ale przybycie kogoś twojego pokroju daje mi wielkie poczucie spełnienia – pamiętam czasy, gdy sama uczyłam się u jednego z waszych szamanów.', 0),
(3085, 'koKR', 'No to $gdotarłeś:dotarłaś;... dobrze, dobrze! Duchy mówiły mi, że niedługo przyjdziesz do Ken\'jaia. Pozwól, że jako jeden z pierwszych powitam cię w Dolinie Prób. To miejsce nie będzie długo twoim domem, ale póki jest, czemu nie wykorzystać go jak najlepiej?', 0),
(3086, 'koKR', 'Już teraz chcesz zadowolić Mai\'ah, $N. To dobrze. Ty okażesz Mai\'ah szacunek, a Mai\'ah może okaże szacunek tobie. Ale dość tego, jesteś tu, żeby uczyć się magii, a nie słuchać gadania Mai\'ah.$B$BJest tylko jedna rzecz o magii, której Mai\'ah nie może cię nauczyć, $N – jak ustrzec się przed jej spaczeniem.', 0),
(3087, 'koKR', 'Ach, więc w końcu $gprzyszedłeś:przyszłaś;. Dobrze. Jen\'shan na ciebie czekała.$B$BWielu myśli, że to łatwa ścieżka, ale Jen\'shan mówi ci, że to nieprawda. Opanowanie bestii Durotaru i dalszych krain wymaga tyle samo umiejętności, co opanowanie sztuk tajemnych albo rozmowa z przodkami.$B$BStrzelanie z łuku czy strzelby może nie być dla ciebie tak niebezpieczne jak rzucanie zaklęć, ale dla twojego wroga na pewno jest równie niebezpieczne.', 0),
(3088, 'koKR', 'Ciii, nie tak głośno. Nie ufam temu Nartokowi. Z kimś, kto musi chować się w jaskini głębiej niż ja, lepiej nie zadzierać.$b$bUfam, że bez problemu się tu $godnalazłeś:odnalazłaś;?', 0),
(3089, 'koKR', 'A więc $gprzybyłeś:przybyłaś;. Zaczynałam się już zastanawiać, kiedy się pokażesz. Wysłałam pergamin jakiś czas temu – nie byłam pewna, czy dotarł.$B$BAle dość gadania... jesteś tu, bo $gzostałeś wybrany:zostałaś wybrana; – $gwybrany:wybrana;, by prowadzić duchowe życie naszego ludu.', 0),
(3090, 'koKR', 'W końcu $gprzybyłeś:przybyłaś;... i to dyskretnie. Dobrze.$b$bNasz świat jest pełen głupców, Asatokta. Nawet potężny Thrall ma większe wady, niż większość potrafi dostrzec. Odwraca się od mocy potrzebnej, by ta kraina stała się całkowicie nasza! Nie jesteśmy już tym samym ludem, którym manipulowały i posługiwały się istoty z Otchłani. Jesteśmy sobą. Jesteśmy dumni... i jesteśmy silni.', 0),
(4402, 'koKR', '$GSkończyłeś:Skończyłaś; zbierać kaktusowe jabłka?', 0),
(4641, 'koKR', 'Pancerz skorpiady nie jest tak gruby, by oprzeć się sile zdeterminowanego wojownika. Uderzaj mocno i bez wahania, a skorpiady okażą się łatwą zdobyczą.', 0),
(5441, 'koKR', 'Leniwe nieroby...$b$b Hę? Masz moją pałkę? $GPrzyłapałeś:Przyłapałaś; jakiegoś peona na spaniu w pracy?!', 0),
(5648, 'koKR', 'Większość uważa za oczywiste, że magia uzdrawiania jest potężna, ale niewielu rozumie, jak bardzo. Możesz utrzymać przy życiu wielu, którzy powinni już spotykać się ze swoimi przodkami. Ta magia uzdrawiania połączona z mocą Wytrwałości to bardzo potężne połączenie czarów. Zapamiętaj to. Przydaje się wszelkiej maści ludziom: wojownikom, magom i wszystkim pomiędzy.', 0),
(6062, 'koKR', 'Powodzenia, $gmłody łowco:młoda łowczyni;.', 0),
(6082, 'koKR', 'Udało ci się oswoić skorpiadę?', 0),
(6083, 'koKR', 'Musisz ćwiczyć, żeby zdobyć umiejętności potrzebne do skutecznego panowania nad zwierzęciem. $GOswoiłeś:Oswoiłaś; pełzacza przyboju?', 0),
(6394, 'koKR', '$GByłeś:Byłaś; w Sabacie Płonącego Ostrza, $N? $GZnalazłeś:Znalazłaś; mój kilof?', 0),
(7664, 'koKR', 'Przyprowadź mi starego raptora, a dam ci nowego, ze świeżo naostrzonymi pazurami! Nowy raptor będzie tak samo szybki jak stary, tylko będzie inaczej wyglądał. Możesz obejrzeć rącze raptory, które tu stoją, i zobaczyć, z czego będziesz wybierać.', 0),
(7665, 'koKR', 'Przyprowadź mi starego raptora, a dam ci nowego, ze świeżo naostrzonymi pazurami! Nowy raptor będzie tak samo szybki jak stary, tylko będzie inaczej wyglądał. Możesz obejrzeć rącze raptory, które tu stoją, i zobaczyć, z czego będziesz wybierać.', 0),
(8150, 'koKR', 'Czy $gdotarłeś:dotarłaś; do Pomnika Groma i $gzłożyłeś:złożyłaś; tam jego trybut?$b$bMiejsce, w którym stoi pomnik, wciąż nosi piętno skażenia Płonącego Legionu. Jeśli nie masz jeszcze wielkiego doświadczenia w przygodach, miej się na baczności, gdy będziesz się zbliżać do pomnika.', 0),
(8609, 'koKR', '$GZdobyłeś:Zdobyłaś; jad?', 0),
(11120, 'koKR', 'Załatwione z tym naszym małym problemem?', 0),
(11219, 'koKR', 'Dzieci Hordy cię potrzebują! Nie opuszczaj ich!', 0),
(11361, 'koKR', 'Udało ci się ugasić jakieś ognie, $n? Plac ćwiczeń jest na zachód od zachodniego wyjścia z Brzytwogóry.', 0),
(11407, 'koKR', 'Wieść o Festiwalu Piwa już rozgłoszona?', 0),
(11408, 'koKR', 'Wieść o Festiwalu Piwa już rozgłoszona? A co ważniejsze, czy ludzie wiedzą już o niesamowitym piwie trolli?', 0),
(11409, 'koKR', 'Jazda na baranach wyścigowych już opanowana?', 0),
(11412, 'koKR', '$GWidziałeś:Widziałaś;, jakiego bałaganu narobił ten goblin? Mam nadzieję, że nie $gszalałeś:szalałaś; za bardzo po bezdrożach.', 0),
(11449, 'koKR', 'Udało ci się ugasić jakieś ognie, $n? Plac ćwiczeń jest na zachód od Brill.', 0),
(11450, 'koKR', 'Udało ci się ugasić jakieś ognie, $n? Plac ćwiczeń jest na południe od Placu Sokolego Skrzydła.', 0),
(11487, 'koKR', 'A co ty tam masz?', 0),
(11966, 'koKR', 'Ogniste pozdrowienia, $N. Witaj na uświęconej ziemi Festiwalu Ognia Letniego Przesilenia.', 0),
(12191, 'koKR', 'Łyknij z kufla, a potem ciśnij kuflem w S.T.O.U.T.-a. Myślę, że wytrzyma takie lanie. Nie ukrad... eee... nie zbudowałbym go, gdyby było inaczej!', 0),
(12492, 'koKR', 'Hej, $N, masz całą twarz umorusaną! Czyżby wizyta w Otchłani Czarnej Góry?', 0),
(14040, 'koKR', 'Placka dyniowego nigdy za wiele.', 0),
(14041, 'koKR', 'Jak ci się podobają Dary Pielgrzymów?', 0),
(14043, 'koKR', 'Witaj z powrotem, $N.', 0),
(14044, 'koKR', 'Dobrze cię znowu widzieć, $N.', 0),
(14047, 'koKR', 'Co cię sprowadza z powrotem do Orgrimmaru, $N?', 0),
(14061, 'koKR', 'Jak idzie polowanie na indyki?', 0),
(25444, 'koKR', 'No i jak, pomagasz z tymi żabami czy nie?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2216, 0, 'koKR', 'Jesteśmy już tak blisko opracowania Nowej Zarazy, której nasza Mroczna Pani tak żarliwie pragnie.', 0),
(3139, 0, 'koKR', 'Throm\'ka, $N. Czasu na rozmowy jest mało, a pracy dużo.', 0),
(3188, 0, 'koKR', 'Chcesz o czymś porozmawiać, $N... chodź, usiądź przy mnie.', 0),
(3337, 0, 'koKR', 'Ciężar topora w dłoni, okrzyk bojowy sojuszników, krew bryzgająca w twarz. Tego pragnie wojownik, $n. Mieczem wyrąbię sobie Pustkowia w imię Hordy.', 0),
(3338, 0, 'koKR', 'Ziemia, woda i niebo są jednym. To twoje oczy oszukują cię takim podziałem. Matka Ziemia jest tym wszystkim i czymś więcej.', 0),
(5887, 0, 'koKR', 'Witaj z powrotem, $n.', 0),
(5888, 0, 'koKR', 'Ziemia cię wzywa, $N. Idź do niej i wiedz, że twoi pobratymcy są dumni z ciebie i ze wszystkiego, czego dokonasz.', 0);
