INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(980, 'koKR', 'Odsuń się od rzeczy porucznika!', 'Odsuń się od rzeczy porucznika!', 0),
(981, 'koKR', '%s słucha raportu $n...', '', 0),
(982, 'koKR', 'Co?! Płonące Ostrze się rozprzestrzenia! Musimy to zbadać!', '', 0),
(983, 'koKR', 'Dziękuję ci, $n. I mój brat ci dziękuje.', '', 0),
(984, 'koKR', '%s miażdży martwy, powykręcany pazur.', '', 0),
(985, 'koKR', 'Nie ścierpimy na naszych ziemiach żadnego sługi demonów!', '', 0),
(986, 'koKR', '%s wpada w trans...', '', 0),
(987, 'koKR', '%s obrywa wyzwoloną magią!', '', 0),
(988, 'koKR', '$n, odkrycie sekretu tych kołnierzy przerasta moje umiejętności...', '', 0),
(989, 'koKR', 'Aaargh!', '', 0),
(990, 'koKR', '%s ogląda palący kołnierz...', '', 0),
(991, 'koKR', 'Ciekawe, bardzo ciekawe. $gZnalazłeś:Znalazłaś; to w Durotarze, $n?', '', 0),
(992, 'koKR', 'Kołnierz rzeczywiście jest przesycony demoniczną mocą, $n. To źle wróży naszemu ludowi.', '', 0),
(993, 'koKR', 'Hm... dobrze, że mi to $gprzyniosłeś:przyniosłaś;, $n.', '', 0),
(994, 'koKR', 'To niebezpieczne urządzenie, $n. Cieszę się, że $gzwróciłeś:zwróciłaś; na nie moją uwagę.', '', 0),
(999, 'koKR', '%s wpada w trans...', '', 0),
(1115, 'koKR', 'Weź kamień ze stołu, $n. Będzie ci potrzebny w twoim zadaniu.', '', 0),
(1295, 'koKR', 'Duch Echeyakee płynie przez ciebie, $n.', '', 0),
(1341, 'koKR', 'Idź szybko, $n. Mój los jest w twoich rękach.', '', 0),
(1421, 'koKR', '%s przyrządza toksynę...', '', 0),
(1422, 'koKR', 'No i proszę, $n. Toksyna jest gotowa.', '', 0),
(2184, 'koKR', '', 'Niech pokój i cierpliwość będą z tobą, $n. Pozostań zawsze $gsilny:silna;.', 0),
(2641, 'koKR', 'Co $gtaki młody śmiałek:taka młoda śmiałkini; jak ty robi u starego rolnika jak ja?', '', 0),
(2646, 'koKR', 'Skończone. Twój pancerz jest gotowy, $n.', '', 0),
(3003, 'koKR', 'Jeśli te nowe ziemie mają stać się nasze, potrzebujemy miejsc, gdzie odpoczną nasze zmęczone bitwami ciała. Odłóż topór przy ogniu i opowiedz o swoich wielkich bitwach.', 'Jeśli te nowe ziemie mają stać się nasze, potrzebujemy miejsc, gdzie odpoczną nasze zmęczone bitwami ciała. Odłóż topór przy ogniu i opowiedz o swoich wielkich bitwach.', 0),
(3275, 'koKR', 'Wpływy Strzaskanej Dłoni dominują na tych ziemiach. Jesteśmy zasłoną, która okrywa Kalimdor: obrońcami, strażą, sędziami, ławą przysięgłych i w ostatecznym rozrachunku katami. Widzimy wszystko, wiemy wszystko.$B$BBardzo się $grozwinąłeś:rozwinęłaś; w czasie służby dla Dłoni, $n. Nadszedł czas, by wysłać cię w teren.$B$BCzy jesteś $ggotów:gotowa; podjąć się kolejnej misji?\n', '', 0),
(3459, 'koKR', 'Który fach?', 'Który fach?', 0),
(4385, 'koKR', '', '$GZaszedłeś:Zaszłaś; dalej niż wielu, $n. Szanuj żywioły wokół siebie, a powiedzie ci się o wiele lepiej niż większości.', 0),
(4761, 'koKR', 'Szukaj „Alchemii i mikstur Yelmaka”. Znajdziesz je pośrodku Dziury, na zachód od wielkiego drzewa.', 'Szukaj „Alchemii i mikstur Yelmaka”. Znajdziesz je pośrodku Dziury, na zachód od wielkiego drzewa.', 0),
(4762, 'koKR', 'Mikstury i oleje – tego nauczy cię Yelmak, jeśli okażesz się $ggodny:godna;. Szukaj jego sklepu pośrodku Dziury.', 'Mikstury i oleje – tego nauczy cię Yelmak, jeśli okażesz się $ggodny:godna;. Szukaj jego sklepu pośrodku Dziury.', 0),
(4763, 'koKR', 'Porozmawiaj z Saru Stalową Furią w „Płonącym Kowadle”. Idź do Doliny Honoru. To na końcu ścieżki, na prawo od Górnictwa „Czerwony Kanion”.', 'Porozmawiaj z Saru Stalową Furią w „Płonącym Kowadle”. Idź do Doliny Honoru. To na końcu ścieżki, na prawo od Górnictwa „Czerwony Kanion”.', 0),
(4764, 'koKR', 'Może Saru Stalowa Furia kiedyś nauczy cię robić topór tak dobry jak mój. Znajdziesz go w „Płonącym Kowadle” w Dolinie Honoru, ścieżką w prawo za Górnictwem „Czerwony Kanion”.', 'Może Saru Stalowa Furia kiedyś nauczy cię robić topór tak dobry jak mój. Znajdziesz go w „Płonącym Kowadle” w Dolinie Honoru, ścieżką w prawo za Górnictwem „Czerwony Kanion”.', 0),
(4765, 'koKR', 'Potrzebujesz Zamji z Paleniska Borstana na górnym poziomie Dziury. Wejdź po schodach po lewej, gdy wchodzisz do Dziury od strony Doliny Siły.', 'Potrzebujesz Zamji z Paleniska Borstana na górnym poziomie Dziury. Wejdź po schodach po lewej, gdy wchodzisz do Dziury od strony Doliny Siły.', 0),
(4767, 'koKR', 'Najlepiej ucz się u Zamji. Idź do Paleniska Borstana na górnym poziomie Dziury – wejdź po schodach po lewej, gdy wchodzisz od strony Doliny Siły.', 'Najlepiej ucz się u Zamji. Idź do Paleniska Borstana na górnym poziomie Dziury – wejdź po schodach po lewej, gdy wchodzisz od strony Doliny Siły.', 0),
(4769, 'koKR', 'Musisz iść do Pracowni run Godana. Szukaj jej w zachodnim krańcu Dziury, tuż obok Doliny Mądrości.', 'Musisz iść do Pracowni run Godana. Szukaj jej w zachodnim krańcu Dziury, tuż obok Doliny Mądrości.', 0),
(4770, 'koKR', 'Zaklniesz mi topór? Chcę coś trwałego. No to może później. Pracownię run Godana znajdziesz w zachodnim krańcu Dziury, przy Dolinie Mądrości.', 'Zaklniesz mi topór? Chcę coś trwałego. No to może później. Pracownię run Godana znajdziesz w zachodnim krańcu Dziury, przy Dolinie Mądrości.', 0),
(4772, 'koKR', 'Arnok robi dobre bandaże. Znajdziesz go w chacie „Zwyciężą najsilniejsi” nad brzegiem jeziora, obok Chaty Duchów w Dolinie Duchów. To powyżej Doliny Siły, na zachód od niej.', 'Arnok robi dobre bandaże. Znajdziesz go w chacie „Zwyciężą najsilniejsi” nad brzegiem jeziora, obok Chaty Duchów w Dolinie Duchów. To powyżej Doliny Siły, na zachód od niej.', 0),
(4773, 'koKR', 'Ktoś chyba musi opatrywać nas, wojowników, po walce. Odszukaj Arnoka w chacie „Zwyciężą najsilniejsi” obok Chaty Duchów w Dolinie Duchów. Spójrz w górę, na zachód od Doliny Siły, i szukaj jeziora. Tam go znajdziesz.', 'Ktoś chyba musi opatrywać nas, wojowników, po walce. Odszukaj Arnoka w chacie „Zwyciężą najsilniejsi” obok Chaty Duchów w Dolinie Duchów. Spójrz w górę, na zachód od Doliny Siły, i szukaj jeziora. Tam go znajdziesz.', 0),
(4774, 'koKR', 'Ten Lumak... zawsze łowi ryby, zamiast walczyć. Znajdziesz go na jego pomoście na jeziorze w Dolinie Honoru. Jak już tam będziesz, pozdrów ode mnie Shankys.', 'Ten Lumak... zawsze łowi ryby, zamiast walczyć. Znajdziesz go na jego pomoście na jeziorze w Dolinie Honoru. Jak już tam będziesz, pozdrów ode mnie Shankys.', 0),
(4775, 'koKR', 'Wędkarstwo to sport dla starców, którzy nie zginęli w boju! Idź poszukać Lumaka nad jeziorem w Dolinie Honoru.', 'Wędkarstwo to sport dla starców, którzy nie zginęli w boju! Idź poszukać Lumaka nad jeziorem w Dolinie Honoru.', 0),
(4776, 'koKR', 'Zioła... musisz porozmawiać z Jandi w jej arboretum w Dziurze. Za Targiem Asorana w Dolinie Mądrości są drewniane schody. Wejdź nimi na górny poziom Dziury, a znajdziesz ją.', 'Zioła... musisz porozmawiać z Jandi w jej arboretum w Dziurze. Za Targiem Asorana w Dolinie Mądrości są drewniane schody. Wejdź nimi na górny poziom Dziury, a znajdziesz ją.', 0),
(4777, 'koKR', 'No, tobie trzeba Arboretum Jandi. Czy ja to właśnie powiedziałem? Glok\'tar, ale jestem zmęczony! Wejdź drewnianymi schodami za Targiem Asorana w Dolinie Mądrości do Dziury, a na górnym poziomie znajdziesz Jandi.', 'No, tobie trzeba Arboretum Jandi. Czy ja to właśnie powiedziałem? Glok\'tar, ale jestem zmęczony! Wejdź drewnianymi schodami za Targiem Asorana w Dolinie Mądrości do Dziury, a na górnym poziomie znajdziesz Jandi.', 0),
(4778, 'koKR', 'Idź do Garbarni „Skóra Kodo” w Dziurze. Pytaj o Karoleka.', 'Idź do Garbarni „Skóra Kodo” w Dziurze. Pytaj o Karoleka.', 0),
