(11676, 'koKR', 'Gdybym nie wiedział, jak jest naprawdę, powiedziałbym, że tę zabawę urządzili orkowie!', 'Gdybym nie wiedział, jak jest naprawdę, powiedziałbym, że tę zabawę urządzili orkowie!', 0),
(11677, 'koKR', '$GWidziałeś:Widziałaś;? Od tego ostatniego fajerwerku mało nie zajęła się koszula tamtego krasnoluda! Ha!', '$GWidziałeś:Widziałaś;? Od tego ostatniego fajerwerku mało nie zajęła się koszula tamtego krasnoluda! Ha!', 0),
(11678, 'koKR', 'Ten promień księżyca przeniesie cię do Orgrimmaru. Użyj zaproszenia, kiedy zechcesz wyruszyć.', 'Ten promień księżyca przeniesie cię do Orgrimmaru. Użyj zaproszenia, kiedy zechcesz wyruszyć.', 0),
