(13309, 'koKR', '', 'Witaj w Ustroniu Obieżyświatów. Jesteśmy tropicielami, którzy przysięgli bronić naszego ludu przed wrogami bliskimi i dalekimi.', 0),
(18608, 'koKR', 'Mistrzów bitewnych znajdziesz w Sali Dzielnych w Dolinie Honoru.', 'Mistrzów bitewnych znajdziesz w Sali Dzielnych w Dolinie Honoru.', 0),
(20975, 'koKR', 'Mistrz Pyreanor jest wśród doradców Thralla w jego twierdzy, Fortecy Grommasza, w Dolinie Mądrości.', 'Mistrz Pyreanor jest wśród doradców Thralla w jego twierdzy, Fortecy Grommasza, w Dolinie Mądrości.', 0),
(22081, 'koKR', 'Szczerze mówiąc, nie jestem pewien, gdzie teraz jest sterowiec...', 'Szczerze mówiąc, nie jestem pewien, gdzie teraz jest sterowiec...', 0),
